(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("philo-the-special-laws-iii-e", [{"sp": "HDR", "t": "Περὶ τῶν ἐν μέρει διαταγμάτων Γ"}, {"sp": "N", "t": "Ἦν ποτε χρόνος, ὅτε φιλοσοφίᾳ σχολάζων καὶ θεωρίᾳ τοῦ κόσμου καὶ τῶν ἐν αὐτῷ τὸν καλὸν καὶ περιπόθητον καὶ μακάριον ὄντως νοῦν ἐκαρπούμην, θείοις ἀεὶ λόγοις συγγινόμενος καὶ δόγμασιν, ὧν ἀπλήστως καὶ ἀκορέστως ἔχων ἐνευφραινόμην, οὐδὲν ταπεινὸν φρονῶν ἢ χαμαίζηλον οὐδὲ περὶ δόξαν ἢ πλοῦτον ἢ τὰς σώματος εὐπαθείας ἰλυσπώμενος, ἀλλ’ ἄνω μετάρσιος ἐδόκουν ἀεὶ φέρεσθαι κατά τινα τῆς ψυχῆς ἐπιθειασμὸν καὶ συμπεριπολεῖν ἡλίῳ καὶ σελήνῃ καὶ σύμπαντι οὐρανῷ τε καὶ κόσμῳ.", "st": "1"}, {"sp": "N", "t": "τότε δὴ τότε διακύπτων ἄνωθεν ἀπ’ αἰθέρος καὶ τείνων ὥσπερ ἀπὸ σκοπιᾶς τὸ τῆς διανοίας ὄμμα κατεθεώμην τὰς ἀμυθήτους θεωρίας τῶν ἐπὶ γῆς ἁπάντων καὶ εὐδαιμόνιζον ἐμαυτὸν ὡς ἀνὰ κράτος ἐκπεφευγότα τὰς ἐν τῷ θνητῷ βίῳ κῆρας.", "st": "2"}, {"sp": "N", "t": "ἐφήδρευε δ’ ἄρα μοι τὸ κακῶν ἀργαλεώτατον, ὁ μισόκαλος φθόνος, ὃς ἐξαπιναίως ἐπιπεσὼν οὐ πρότερον ἐπαύσατο καθέλκων πρὸς βίαν ἤ με καταβαλεῖν εἰς μέγα πέλαγος τῶν ἐν πολιτείᾳ φροντίδων, ἐν ᾧ φορούμενος οὐδ’ ὅσον ἀνανήξασθαι δύναμαι.", "st": "3"}, {"sp": "N", "t": "στένων δ’ ὅμως ἀντέχω τὸν ἐκ πρώτης ἡλικίας ἐνιδρυμένον τῇ ψυχῇ παιδείας ἵμερον ἔχων, ὃς ἔλεόν μου καὶ οἶκτον ἀεὶ λαμβάνων ἀνεγείρει καὶ ἀνακουφίζει. διὰ τοῦτον ἔστιν ὅτε τὴν κεφαλὴν ἐπαίρω καὶ τοῖς τῆς ψυχῆς ὄμμασιν ἀμυδρῶς μὲν — τὸ γὰρ ὀξυδερκὲς αὐτῶν ἡ τῶν ἀλλοκότων πραγμάτων ἀχλὺς ἐπεσκίασεν — ἀλλ’ ἀναγκαίως γοῦν περιβλέπομαι τἀν κύκλῳ καθαρᾶς καὶ ἀμιγοῦς κακῶν ζωῆς σπάσαι γλιχόμενος.", "st": "4"}, {"sp": "N", "t": "εἰ δέ μοι καὶ ἐξ ἀπροσδοκήτου βραχεῖα γένοιτο εὐδία καὶ γαλήνη θορύβων τῶν ἐν πολιτείᾳ, ὑπόπτερος ἐπικυματίζω μόνον οὐκ ἀεροπορῶν, αὔραις τῆς ἐπιστήμης καταπνεόμενος, ἥ με πολλάκις ἀναπείθει δραπετεύειν συνημερεύσοντα αὐτῇ καθάπερ ἀπὸ δεσποτῶν ἀμειλίκτων, οὐκ ἀνθρώπων μόνον ἀλλὰ καὶ πραγμάτων ἀλλαχόθεν ἄλλων χειμάρρου τρόπον ἐπεισχεομένων.", "st": "5"}, {"sp": "N", "t": "ἀλλὰ γὰρ καὶ ἐπὶ τούτοις θεῷ προσῆκον εὐχαριστεῖν, ὅτι καίτοι κατακλυζόμενος οὐκ ἐγκαταπίνομαι βύθιος· ἀλλὰ καὶ τοὺς τῆς ψυχῆς ὀφθαλμούς, οὓς ἀπογνώσει τινὸς χρηστῆς ἐλπίδος ᾠήθην ἤδη πεπηρῶσθαι, διοίγω καὶ φωτὶ τῷ σοφίας ἐναυγάζομαι μὴ πάντα τὸν βίον τῷ σκότῳ παραδοθείς. ἰδού γέ τοι τολμῶ μὴ μόνον τοῖς ἱεροῖς Μωυσέως ἑρμηνεύμασιν ἐντυγχάνειν, ἀλλὰ καὶ φιλεπιστημόνως διακύπτειν εἰς ἕκαστον καὶ ὅσα μὴ γνώριμα τοῖς πολλοῖς διαπτύττειν καὶ ἀναφαίνειν.", "st": "6"}, {"sp": "N", "t": "Ἐπεὶ δὲ τῶν δέκα λογίων, ἅπερ αὐτὸς ἔχρησεν ὁ θεὸς ἄνευ προφήτου καὶ ἑρμηνέως, πέντε μὲν εἴρηται τὰ χαραχθέντα ἐν τῇ προτέρᾳ δέλτῳ καὶ ὅσα τῶν κατὰ μέρος συνέτεινεν εἰς ταῦτα, δεῖ δ’ ἐν τῷ παρόντι καὶ τὰ λοιπὰ τὰ κατὰ τὴν ἑτέραν δέλτον ὡς οἷόν τε ἄριστα συνυφῆναι, πειράσομαι πάλιν καθ’ ἕκαστον τῶν γενῶν ἐφαρμόζειν τοὺς ἐν εἴδει νόμους.", "st": "7"}, {"sp": "N", "t": "ἐν δὲ τῇ δευτέρᾳ δέλτῳ πρῶτον γράμμα τοῦτ’ ἐστίν· “οὐ μοιχεύσεις”, ὅτι, οἶμαι, πανταχοῦ τῆς οἰκουμένης μέγα πνεῖ ἡ ἡδονὴ καὶ οὐδὲν μέρος τὴν δυναστείαν αὐτῆς ἐκπέφευγεν, οὐ τῶν κατὰ γῆν, οὐ τῶν κατὰ θάλατταν, οὐ τῶν ἐν ἀέρι· χερσαῖά τε γὰρ καὶ πτηνὰ καὶ ἔνυδρα πάντα διὰ πάντων τέθηπε καὶ περιέπει καὶ τοῖς ἐπιτάγμασιν αὐτῆς ὑπείκει πρός τι βλέμμα καὶ νεῦμα ἀφορῶντα κἂν εἰ φρυάττοιτο ὑπ’ ἀλαζονείας ἀσμενίζοντα καὶ μόνον οὐ φθάνοντα τὰς προστάξεις ὀξύτητι καὶ ἀνυπερθέτῳ τάχει τῶν ὑπηρεσιῶν.", "st": "8"}, {"sp": "N", "t": "ἔχει μὲν οὖν καὶ ἡ κατὰ φύσιν ἡδονὴ πολλὴν καὶ πολλάκις μέμψιν, ὅταν ἀμέτρως καὶ ἀκορέστως χρῆταί τις αὐτῇ, καθάπερ οἱ περὶ ἐδωδὴν ἄπληστοι, κἂν εἰ μηδὲν τῶν ἀπαγορευομένων προσφέροιντο, καὶ οἱ φιλογύναιοι συνουσίαις ἐπιμεμηνότες καὶ λαγνίστερον ὁμιλοῦντες γυναιξὶν οὐκ ἀλλοτρίαις ἀλλὰ ταῖς ἑαυτῶν.", "st": "9"}, {"sp": "N", "t": "ἡ δὲ μέμψις σώματός ἐστι μᾶλλον ἢ ψυχῆς κατὰ τοὺς πολλούς, πολλὴν μὲν ἔχοντος εἴσω φλόγα, ἣ τὴν παραβληθεῖσαν τροφὴν ἐξαναλίσκουσα ἑτέραν οὐκ εἰς μακρὰν ἐπιζητεῖ, πολλὴν δὲ ἰκμάδα, ἧς τὸ ῥοῶδες διὰ τῶν γεννητικῶν ἀποχετεύεται κνησμοὺς καὶ ὀδαξησμοὺς ἐμποιοῦν καὶ γαργαλισμοὺς ἀπαύστους.", "st": "10"}, {"sp": "N", "t": "τοὺς δὲ καὶ γυναιξὶν ἄλλων καὶ ἔστιν ὅτε οἰκείων καὶ φίλων ἐπιμεμηνότας καὶ ἐπὶ λύμῃ τῶν πλησίον ζῶντας, ὅλα γένη πολυάνθρωπα κιβδηλεύειν ἐπιχειροῦντας καὶ τὰς μὲν ἐπὶ γάμοις εὐχὰς παλιμφήμους τὰς δὲ ἐπὶ τέκνοις ἐλπίδας ἀτελεῖς ἀπεργαζομένους, ἀνίατον νόσον ψυχῆς νοσοῦντας, ὡς κοινοὺς ἐχθροὺς ἅπαντος ἀνθρώπων γένους κολαστέον θανάτῳ, ὡς μήτε ζῶντες ἐν ἀδείᾳ πλείους διαφθείροιεν οἴκους μήτε διδάσκαλοι γένοιντο ἑτέρων, οἷς τὰ πονηρὰ τῶν ἐπιτηδευμάτων ζηλοῦν ἐπιμελές.", "st": "11"}, {"sp": "N", "t": "Εὖ μέντοι καὶ τὰ ἄλλα τὰ περὶ τὰς ὁμιλίας ὁ νόμος διετάξατο. κελεύει γὰρ οὐ μόνον ἀλλοτρίων ἀπέχεσθαι γυναικῶν, ἀλλὰ καὶ χηρευουσῶν μητρυιῶν, αἷς οὐ θέμις συνέρχεσθαι.", "st": "12"}, {"sp": "N", "t": "τὸ Περσικὸν ἔθος εὐθὺς ἀποστραφεὶς καὶ μυσαξάμενος ἀπεῖπεν ὡς μέγιστον ἀνοσιούργημα· μητέρας γὰρ οἱ ἐν τέλει Περσῶν τὰς ἑαυτῶν ἄγονται καὶ τοὺς φύντας ἐκ τούτων εὐγενεστάτους νομίζουσι καὶ βασιλείας, ὡς λόγος, τῆς μεγίστης ἀξιοῦσιν·", "st": "13"}, {"sp": "N", "t": "οὗ τί ἂν γένοιτο δυσσεβέστερον ἀνοσιούργημα; πατρὸς εὐνὴν τετελευτηκότος, ἣν ἄψαυστον ὡς ἱερὰν ἐχρῆν φυλάττεσθαι, καταισχύνειν, γήρως δὲ καὶ μητρὸς αἰδῶ μὴ λαμβάνειν, τὸν αὐτὸν τῆς αὐτῆς υἱὸν καὶ ἄνδρα γίνεσθαι καὶ πάλιν τὴν αὐτὴν τοῦ αὐτοῦ καὶ γυναῖκα καὶ μητέρα, καὶ τοὺς ἀμφοῖν παῖδας τοῦ μὲν πατρὸς ἀδελφούς, υἱωνοὺς δὲ τῆς μητρός, καὶ τὴν μὲν ὧν ἔτεκε μητέρα τε καὶ μάμμην, τὸν δὲ ὧν ἐγέννησεν ἐν ταὐτῷ πατέρα τε καὶ ὁμομήτριον ἀδελφόν —", "st": "14"}, {"sp": "N", "t": "ταῦτ’ ἐπράχθη τὸ παλαιὸν καὶ παρ’ Ἕλλησιν ἐν Θήβαις ἐπὶ τοῦ Λαΐου παιδὸς Οἰδίποδος καὶ ἐπράχθη κατ’ ἄγνοιαν, οὐχ ἑκουσίῳ γνώμῃ, καὶ ὅμως τοσαύτην κακῶν φορὰν ἤνεγκεν ὁ γάμος, ὡς μηδὲν ἐλλειφθῆναι τῶν εἰς τὴν ἀνωτάτω βαρυδαιμονίαν.", "st": "15"}, {"sp": "N", "t": "πολέμων τε γὰρ ἐμφυλίων καὶ ξενικῶν διαδοχαὶ καθάπερ κλῆρος παισὶ καὶ ἐκγόνοις παρὰ πατέρων καὶ προγόνων ἀπελείπετο καὶ πορθήσεις πόλεων τῶν ἐν τῇ Ἑλλάδι μεγίστων ἐγίνοντο καὶ φθοραὶ στρατιωτικῶν δυνάμεων ἐγχωρίων τε καὶ τῶν κατὰ συμμαχίαν ἀφικνουμένων καὶ ἡγεμόνων τῶν παρ’ ἑκατέροις ἀρίστων ἐπάλληλοι φθοραὶ καὶ διὰ τὰς περὶ κράτους [καὶ] ἀρχῆς ἀσυμβάτους ἔχθρας ἀδελφοκτονίαι, δι’ ἃς οὐ μόνον αἱ συγγένειαι καὶ πατρίδες ἀλλὰ καὶ ἡ πλείστη μοῖρα τοῦ Ἑλληνικοῦ παντὸς ἐξεφθάρη πανωλεθρίᾳ· κεναὶ γὰρ αἱ πρότερον εὐανδροῦσαι πόλεις οἰκητόρων μνημεῖα τῶν τῆς Ἑλλάδος συμφορῶν ὑπελείφθησαν, ἀτυχὴς θέα τοῖς ὁρῶσιν.", "st": "16"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ Πέρσαι, παρ’ οἷς ταῦτα ἐπιτηδεύεται, τῶν παραπλησίων κακῶν ἀμοιροῦσιν· ἀεὶ γὰρ ἐν στρατείαις καὶ μάχαις εἰσὶ κτείνοντες καὶ κτεινόμενοι καὶ τοτὲ μὲν τοὺς πλησιοχώρους κατατρέχοντες τοτὲ δὲ τοὺς ἐπανισταμένους ἀμυνόμενοι· πολλοὶ δὲ πολλαχόθεν ἐπανίστανται, τοῦ βαρβαρικοῦ μὴ πεφυκότος ἠρεμεῖν· πρὶν γοῦν καταλυθῆναι τὴν ἐν χερσὶ στάσιν, ἑτέρα φύεται, ὡς μηδένα τοῦ ἔτους ὑπεξῃρῆσθαι καιρὸν εἰς ἡσυχίαν, ἀλλὰ καὶ θέρους καὶ χειμῶνος μεθ’ ἡμέραν καὶ νύκτωρ ὁπλοφορεῖν, πλείω χρόνον ἐν τοῖς στρατοπέδοις ἐν ὑπαίθρῳ ταλαιπωροῦντας ἢ ἐν ταῖς πόλεσιν οἰκοῦντας διὰ πολλὴν ἔνδειαν εἰρήνης.", "st": "17"}, {"sp": "N", "t": "ἐῶ λέγειν τὰς τῶν βασιλέων μεγάλας καὶ ὑπερόγκους εὐπραγίας, οἷς ἀγώνισμα πρῶτον εὐθὺς ἅμα τῇ παραλήψει τῆς ἡγεμονίας τὸ μέγιστον ἄγος, ἀδελφοκτονία, μαντευομένων τὴν ἐκ τῶν ἀδελφῶν γενησομένην ἴσως ἐπίθεσιν ὑπὲρ τοῦ δοκεῖν εὐλόγως κτείνειν.", "st": "18"}, {"sp": "N", "t": "ἅπερ μοι δοκεῖ πάντα συμβαίνειν διὰ τὰς ἀναρμόστους υἱῶν πρὸς μητέρας ὁμιλίας, τῆς ἐφόρου τῶν ἀνθρωπείων δίκης ἀμυνομένης τῶν ἀνοσιουργημάτων τοὺς ἀσεβοῦντας· ἀσεβοῦσι δ’ οὐχ οἱ δρῶντες μόνον, ἀλλὰ καὶ ὅσοι τοῖς δρῶσιν ἑκουσίῳ γνώμῃ συνεπιγράφονται.", "st": "19"}, {"sp": "N", "t": "τοσαύτην δὲ ὁ ἡμέτερος νόμος φυλακὴν πεποίηται τοῦ πράγματος, ὥστε οὐδὲ προγονῷ τελευτήσαντος πατρὸς ἄγεσθαι μητρυιὰν ἐφῆκε, διά τε τὴν εἰς τὸν πατέρα τιμὴν καὶ διότι μητρυιᾶς καὶ μητρὸς ὄνομα συγγενές, εἰ καὶ μὴ τὸ τῆς ψυχῆς συνῳδὸν πάθος·", "st": "20"}, {"sp": "N", "t": "ὁ γὰρ ἀλλοτρίας ἀπέχεσθαι διδαχθείς, ὅτι μητρυιὰ προσερρήθη, πολὺ μᾶλλον ἀφέξεται τῆς φύσει μητρός· καὶ εἴ τις διὰ τὴν ἐπὶ τῷ πατρὶ μνήμην αἰδεῖται τὴν ἐκείνου ποτὲ γενομένην γυναῖκα, δῆλός ἐστιν ἕνεκα τῆς εἰς ἀμφοτέρους τοὺς γονεῖς τιμῆς οὐδὲν βουλευσόμενος ἐπὶ τῇ μητρὶ νεώτερον, ἐπεὶ καὶ σφόδρα ἐστὶν εὔηθες ἡμίσει μέρει τοῦ γένους χαριζόμενον ὁλοκλήρου καὶ παντελοῦς ὀλιγωρεῖν δοκεῖν.", "st": "21"}, {"sp": "N", "t": "Ἑξῆς ἐστι παράγγελμα μηδ’ ἀδελφὴν ἐγγυᾶσθαι, πάνυ σπουδαῖον καὶ συντεῖνον εἰς ἐγκράτειαν ὁμοῦ καὶ εὐκοσμίαν. ὁ μὲν οὖν Ἀθηναῖος Σόλων ὁμοπατρίους ἐφεὶς ἄγεσθαι τὰς ὁμομητρίους ἐκώλυσεν, ὁ δὲ Λακεδαιμονίων νομοθέτης ἔμπαλιν τὸν ἐπὶ ταῖς ὁμογαστρίοις γάμον ἐπιτρέψας τὸν πρὸς τὰς ὁμοπατρίους ἀπεῖπεν·", "st": "22"}, {"sp": "N", "t": "ὁ δὲ τῶν Αἰγυπτίων χλεύην θέμενος τὴν ἑκατέρων εὐλάβειαν ὡς ἡμίεργα διαταταττομένων εὐφόρησεν εἰς ἀσέλγειαν, ἐπιδαψιλευόμενος δυσθεράπευτον κακὸν σώμασι καὶ ψυχαῖς ἀκρασίαν καὶ παρασχὼν ἄδειαν ἁπάσας ἀδελφὰς ἄγεσθαι, τάς τε ἰδίας τοῦ ἑτέρου τῶν γονέων, τοῦδε ἢ τοῦδε, καὶ τὰς ἐξ ἀμφοῖν καὶ τὰς οὐ νεωτέρας μόνον ἀλλὰ καὶ πρεσβυτέρας καὶ ἰσήλικας· καὶ δίδυμοι γὰρ πολλάκις ἐγεννήθησαν, οὓς ἡ μὲν φύσις ἅμα τῇ γενέσει διήρτησε καὶ διέζευξεν, ἡ δ’ ἀκολασία καὶ φιληδονία εἰς κοινωνίαν ἐκάλεσεν ἀκοινώνητον καὶ ἁρμονίαν ἀνάρμοστον.", "st": "23"}, {"sp": "N", "t": "ἅπερ ἐκμυσαξάμενος ὁ ἱερώτατος Μωυσῆς ὡς ἀλλότρια καὶ ἐχθρὰ πολιτείας ἀνεπιλήπτου καὶ προτρέποντα καὶ ἀλείφοντα πρὸς τὰ αἴσχιστα τῶν ἐπιτηδευμάτων ἀνὰ κράτος ἀπεῖπεν ἀδελφῇ συνέρχεσθαι, εἴτε ἐξ ἀμφοῖν εἴτε καὶ μόνου γένοιτο τοῦ ἑτέρου.", "st": "24"}, {"sp": "N", "t": "τί γὰρ δεῖ τὸ τῆς αἰδοῦς κάλλος αἰσχύνειν; τί δ’ ἀχρωμάτους κατασκευάζειν παρθένους, ἃς ἐρυθριᾶν ἀναγκαῖον; τί δὲ τὰς πρὸς τοὺς ἄλλους ἀνθρώπους κοινωνίας καὶ ἐπιμιξίας ἐπέχειν εἰς βραχὺ χωρίον τὸ ἑκάστης οἰκίας συνωθοῦντας μέγα καὶ λαμπρὸν γένος ἐκτείνεσθαι καὶ χεῖσθαι δυνάμενον εἰς ἠπείρους καὶ νήσους καὶ τὴν οἰκουμένην πᾶσαν; αἱ γὰρ πρὸς τοὺς ὀθνείους ἐπιγαμίαι καινὰς ἀπεργάζονται συγγενείας τῶν ἀφ’", "st": "25"}, {"sp": "N", "t": "αἵματος οὐκ ἀποδεούσας. ὧν χάριν πολλὰς καὶ ἄλλας ὁμιλίας ἐκώλυσε προστάξας μὴ θυγατριδῆν, μὴ υἱιδῆν, μὴ τηθίδα πρὸς πατρὸς ἢ μητρός, μὴ θείου ἢ υἱοῦ ἢ ἀδελφοῦ γυναῖκα γενομένην ἐγγυᾶσθαι, μηδ’ αὖ προγονὴν ἢ χήραν ἢ παρθένον ζώσης μὲν τῆς γυναικὸς — ἄπαγε — ἀλλὰ μηδ’ ἀποθανούσης· δυνάμει γὰρ ὅ γε πατρωὸς πατὴρ ὀφείλων τὴν ἐκ τῆς γυναικὸς ἐν τάξει θυγατρὸς τίθεσθαι.", "st": "26"}, {"sp": "N", "t": "πάλιν δύο ἀδελφὰς ἄγεσθαι τὸν αὐτὸν οὐκ ἐπιτρέπει, οὔτ’ ἐν τῷ αὐτῷ οὔτ’ ἐν διαφέρουσι χρόνοις, κἂν τύχῃ τις ἣν προέγημεν ἀπεωσμένος· ζώσης γὰρ ἔτι τῆς συνοικούσης, εἴτε καὶ ἀπηλλαγμένης, ἐάν τε χηρεύῃ ἐάν τε καὶ ἑτέρῳ γαμηθῇ, τὴν ἀδελφὴν οὐχ ὅσιον ὑπέλαβεν ἐπὶ τὰ τῆς ἠτυχηκυίας παρέρχεσθαι, προδιδάσκων τὰ συγγενικὰ δίκαια μὴ λύειν μηδ’ ἐπιβαίνειν πταίσμασι τῆς οὕτως ἡνωμένης κατὰ γένος μηδ’ ἐναβρύνεσθαι καὶ ἐντρυφᾶν θεραπευομένην ὑπὸ τῶν ἐχθρῶν ἐκείνης καὶ ἀντιθεραπεύουσαν αὐτούς.", "st": "27"}, {"sp": "N", "t": "ἐγείρονται γὰρ ἐκ τούτων χαλεπαὶ ζηλοτυπίαι καὶ δυσπαρηγόρητοι φιλονεικίαι φορὰς ἀμυθήτους ἐπάγουσαι κακῶν· ὅμοιον γὰρ ὡς εἰ καὶ τὰ μέρη τοῦ σώματος τῆς κατὰ φύσιν ἁρμονίας ἐκστάντα καὶ κοινωνίας στασιάζοι πρὸς ἄλληλα, ὃ νόσους ἀνιάτους ἀπεργάζεται καὶ φθοράς· ἀδελφαὶ δέ, εἰ καὶ διαιρετὰ μέρη γεγόνασιν, ἀλλ’ οὖν ἁρμόζονται καὶ ἑνοῦνται φύσει καὶ συγγενείᾳ μιᾷ· ἡ δὲ ζηλοτυπία, πάθος ἀργαλεώτατον,", "st": "28"}, {"sp": "N", "t": "ἀπορρήττουσα χαλεπὰ καινουργεῖ κακὰ καὶ δυσίατα. ἀλλὰ μηδὲ ἀλλοεθνεῖ, φησί, κοινωνίαν γάμου συντίθεσο, μή ποτε μαχομένοις ἔθεσιν ὑπαχθεὶς ἐνδῷς καὶ τῆς πρὸς εὐσέβειαν ὁδοῦ λάθῃς διαμαρτὼν πρὸς ἀνοδίαν ἐκτραπείς· καὶ τάχα μὲν αὐτὸς ἀνθέξεις ἐκ πρώτης ἡλικίας ἡρματισμένος ὑποθήκαις ἀρίσταις, ἃς οἱ γονεῖς κατεπᾴδοντες ἀεὶ τοὺς ἱεροὺς νόμους ὑφηγοῦντο· δέος δὲ οὐ μικρόν ἐστι περὶ υἱῶν καὶ θυγατέρων, ἴσως γὰρ δελεασθέντες νόθοις πρὸ γνησίων ἔθεσι κινδυνεύουσι τὴν τοῦ ἑνὸς θεοῦ τιμὴν ἀπομαθεῖν, ὅπερ ἐστὶν ἀρχὴ καὶ τέλος τῆς ἀνωτάτω βαρυδαιμονίας.", "st": "29"}, {"sp": "N", "t": "ἐὰν δέ, φησίν, ἀνδρὸς ἀπαλλαγεῖσα γυνὴ καθ’ ἣν ἂν τύχῃ πρόφασιν ἑτέρῳ γημαμένη πάλιν χηρεύσῃ, ζῶντος ἢ καὶ τετελευτηκότος τοῦ δευτέρου, μὴ ἐπανίτω πρὸς ἄνδρα τὸν πρότερον, ἀλλὰ πᾶσι τοῖς ἄλλοις ἔνσπονδος μᾶλλον ἢ τῷδε γενέσθω, θεσμοὺς παραβᾶσα τοὺς ἀρχαίους, ὧν ἐξελάθετο φίλτρα καινὰ πρὸ τῶν παλαιῶν ἑλομένη.", "st": "30"}, {"sp": "N", "t": "πρὸς δὲ συμβάσεις εἴ τις ἐθέλει χωρεῖν ἀνὴρ τῇ τοιαύτῃ γυναικί, μαλακίας καὶ ἀνανδρίας ἐκφερέσθω δόξαν, ἐκτετμημένος τῆς ψυχῆς τὸ βιωφελέστατον, μισοπόνηρον πάθος, ὑφ’ οὗ καὶ τὰ οἴκων καὶ τὰ πόλεων πράγματα κατορθοῦται, καὶ δύο τὰ μέγιστα τῶν ἀδικημάτων εὐφόρως ἀπομαξάμενος, μοιχείαν τε καὶ προαγωγείαν· αἱ γὰρ αὖθις καταλλαγαὶ μηνύματ’ εἰσὶ τοῦ ἑκατέρου· θανάτου δίκην τινέτω σὺν τῇ γυναικί.", "st": "31"}, {"sp": "N", "t": "Φορὰ τῶν μηνιαίων ὁπότε γένοιτο, μὴ ψαυέτω γυναικὸς ἀνήρ, ἀλλὰ τὸν χρόνον ἐκεῖνον ὁμιλίας ἀνεχέτω νόμον φύσεως αἰδούμενος καὶ ἅμα προδιδασκόμενος μὴ ἀτελεῖς γονὰς ἀκαίρου καὶ ἀμούσου χάριν ἡδονῆς προΐεσθαι· ὅμοιον γὰρ ὡς εἴ τις γεωπόνος ὑπὸ μέθης ἢ φρενοβλαβείας πυροὺς καὶ κριθὰς εἰς λίμνας καὶ χειμάρρους ἀντὶ πεδίων σπείροι, ξηραῖς γὰρ γενομέναις ταῖς ἀρούραις καταβάλλεσθαι χρὴ τὸν σπόρον εἰς εὐκαρπίαν.", "st": "32"}, {"sp": "N", "t": "καθαίρει δὲ καὶ ἡ φύσις ἑκάστῳ μηνὶ τὴν μήτραν οἷά τινα θαυμαστὴν ἄρουραν, ἧς τὸν καιρὸν ἀγαθοῦ γεωργοῦ τρόπον ἐπιτηρητέον, ἵν’ ἔτι μὲν ἐπικλυζομένης ἐπέχοι τὸν σπόρον — λήσεται γὰρ τῇ φορᾷ κατασυρεὶς ὑπὸ τῆς ὑγρότητος τοὺς σπερματικοὺς τόνους οὐ χαλασθεὶς μόνον ἀλλὰ καὶ εἰς ἅπαν ἐκλυθείς· οὗτοι δ’ εἰσὶν οἱ ἐν τῇ μήτρᾳ τῷ τῆς φύσεως ἐργαστηρίῳ ζῳοπλαστοῦντες καὶ τῶν μερῶν ἕκαστον σώματός τε καὶ ψυχῆς ἀκρότητι τέχνης τελεσιουργοῦντες —, εἰ δ’ ἐπίσχοι τὰ μηνιαῖα, θαρρῶν ἤδη γόνιμα κατασπείροι μηκέτι φθορὰς τῶν καταβληθησομένων δεδιώς.", "st": "33"}, {"sp": "N", "t": "ὀνειδιστέον καὶ τοῖς σκληρὰν καὶ λιθώδη γῆν ἀροῦσιν· οὗτοι δὲ τίνες ἂν εἶεν ἢ οἱ στείραις συνερχόμενοι γυναιξί; θήρᾳ γὰρ αὐτὸ μόνον ἡδονῆς ἀκράτορος ὡς οἱ λαγνίστατοι τὰς γονὰς ἑκουσίῳ γνώμῃ διαφθείρουσιν· ἐπεὶ τίνος ἄλλου χάριν ἐγγυῶνται τὰς τοιαύτας; οὐ μὴν δι’ ἐλπίδα τέκνων, ἣν ἴσασιν ἐξ ἀνάγκης ἀτελῆ γενησομένην, ἀλλὰ δι’ ὑπερβάλλοντα οἶστρον καὶ ἀκρασίαν ἀνίατον.", "st": "34"}, {"sp": "N", "t": "ὅσοι μὲν οὖν ἄγονται κόρας ἀγνοίᾳ τοῦ πῶς ἔχουσιν εὐθὺς εὐτοκίας ἢ τοὐναντίον, ὁπόταν χρόνῳ μακρῷ ὕστερον ἐκ τῆς ἀγονίας αἰσθανόμενοι στείρας αὐτὰς μὴ ἀποπέμπωνται, συγγνώμης εἰσὶν ἐπάξιοι συνηθείας, βιαστικωτάτου πράγματος, ἡττώμενοι καὶ φίλτρα ἀρχαῖα συμβιώσει μακρᾷ ταῖς ψυχαῖς ἐνεσφραγισμένα λύειν ἀδυνατοῦντες.", "st": "35"}, {"sp": "N", "t": "ὅσοι δὲ προδεδοκιμασμένας ἑτέροις ἀνδράσιν ὡς εἰσὶν ἄγονοι μνῶνται συῶν τρόπον ἢ τράγων ὀχεύοντες αὐτὸ μόνον, ἐν ἀσεβῶν στήλαις ἐγγραφέσθωσαν ὡς ἀντίπαλοι θεοῦ· τῷ μὲν γὰρ ἅτε φιλοζῴῳ καὶ φιλανθρώπῳ δι’ ἐπιμελείας τῆς πάσης ἐστὶ σωτηρίαν καὶ μονὴν τοῖς γένεσιν ἅπασιν ἐργάζεσθαι, οἱ δ’ ἅμα τῇ καταβολῇ σβέσιν τοῖς σπέρμασι τεχνάζοντες ἐχθροὶ τῆς φύσεως ὁμολογουμένως εἰσίν.", "st": "36"}, {"sp": "N", "t": "Ἐπεισκεκώμακε δὲ ταῖς πόλεσιν ἕτερον πολὺ τοῦ λεχθέντος μεῖζον κακόν, τὸ παιδεραστεῖν, ὃ πρότερον μὲν καὶ λεχθῆναι μέγα ὄνειδος ἦν, νυνὶ δ’ ἐστὶν αὔχημα οὐ τοῖς δρῶσι μόνον, ἀλλὰ καὶ τοῖς πάσχουσιν, οἳ νόσον θήλειαν νοσεῖν ἐθιζόμενοι τάς τε ψυχὰς καὶ τὰ σώματα διαρρέουσι μηδὲν ἐμπύρευμα τῆς ἄρρενος γενεᾶς ἐῶντες ὑποτύφεσθαι, περιφανῶς οὕτως τὰς τῆς κεφαλῆς τρίχας ἀναπλεκόμενοι καὶ διακοσμούμενοι καὶ ψιμμυθίῳ καὶ φύκεσι καὶ τοῖς ὁμοιοτρόποις τὰς ὄψεις τριβόμενοι καὶ ὑπογραφόμενοι καὶ εὐώδεσι μύροις λίπα χριόμενοι — προσαγωγὸν γὰρ μάλιστα ἐν τοῖς τοιούτοις τὸ εὐῶδες ἐν ἅπασι τοῖς εἰς εὐκοσμίαν ἠσκημένοις —, καὶ τὴν ἄρρενα φύσιν ἐπιτηδεύσει τεχνάζοντες εἰς θήλειαν μεταβάλλειν οὐκ ἐρυθριῶσι.", "st": "37"}, {"sp": "N", "t": "καθ’ ὧν φονᾶν ἄξιον νόμῳ πειθαρχοῦντας, ὃς κελεύει τὸν ἀνδρόγυνον τὸ φύσεως νόμισμα παρακόπτοντα νηποινεὶ τεθνάναι, μηδεμίαν ἡμέραν ἀλλὰ μηδ’ ὥραν ἐώμενον ζῆν, ὄνειδος αὑτοῦ καὶ οἰκίας καὶ πατρίδος ὄντα καὶ τοῦ σύμπαντος ἀνθρώπων γένους.", "st": "38"}, {"sp": "N", "t": "ὁ δὲ παιδεραστὴς ἴστω τὴν αὐτὴν δίκην ὑπομένων, ἐπειδὴ τὴν παρὰ φύσιν ἡδονὴν διώκει καὶ τὰς πόλεις τό γε ἐπ’ αὐτὸν ἧκον μέρος ἐρήμους καὶ κενὰς ἀποδείκνυσιν οἰκητόρων διαφθείρων τὰς γονὰς καὶ προσέτι τῶν μεγίστων κακῶν, ἀνανδρίας καὶ μαλακίας, ὑφηγητὴς καὶ διδάσκαλος ἀξιοῖ γενέσθαι τοὺς νέους ὡραΐζων καὶ τὸ τῆς ἀκμῆς ἄνθος ἐκθηλύνων, ὃ πρὸς ἀλκὴν καὶ ῥώμην ἀλείφειν ἁρμόττον ἦν, καὶ τελευταῖον ὅτι κακοῦ τρόπον γεωργοῦ τὰς μὲν βαθυγείους καὶ εὐκάρπους ἀρούρας χερσεύειν ἐᾷ μηχανώμενος ἐπ’ αὐταῖς ἀγονίαν, ἐξ ὧν δ’ οὐδὲν βλάστημα προσδοκᾶται τὸ παράπαν, εἰς ταῦτα πονεῖται μεθ’ ἡμέραν τε καὶ νύκτωρ.", "st": "39"}, {"sp": "N", "t": "αἴτιον δ’ οἶμαι τὸ παρὰ πολλοῖς τῶν δήμων ἀκρασίας καὶ μαλακίας ἆθλα κεῖσθαι· τοὺς γοῦν ἀνδρογύνους ἔστιν ἰδεῖν διὰ πληθυούσης ἀγορᾶς ἀεὶ σοβοῦντας κἀν ταῖς ἑορταῖς προπομπεύοντας καὶ τὰ ἱερὰ τοὺς ἀνιέρους διειληχότας καὶ μυστηρίων καὶ τελετῶν κατάρχοντας καὶ τὰ Δήμητρος ὀργιάζοντας.", "st": "40"}, {"sp": "N", "t": "ὅσοι δ’ αὐτῶν τὴν καλὴν νεανιείαν προσεπιτείνοντες εἰς ἅπαν ὠρέχθησαν μεταβολῆς τῆς εἰς γυναῖκας καὶ τὰ γεννητικὰ προσαπέκοψαν, ἁλουργίδας ἀμπεχόμενοι καθάπερ οἱ μεγάλων ἀγαθῶν αἴτιοι ταῖς πατρίσι προέρχονται δορυφορούμενοι, τοὺς ὑπαντῶντας ἐπιστρέφοντες.", "st": "41"}, {"sp": "N", "t": "εἰ δ’ ἦν ἀγανάκτησις οἵα παρὰ τῷ ἡμετέρῳ νομοθέτῃ κατὰ τῶν τὰ τοιαῦτα τολμώντων καὶ ὡς κοινὰ τῶν πατρίδων ἄγη καὶ μιάσματα δίχα συγγνώμης ἀνῃροῦντο, πολλοὺς ἂν ἑτέρους συνέβαινε νουθετεῖσθαι· αἱ γὰρ τῶν προκαταγνωσθέντων ἀπαραίτητοι τιμωρίαι ἀνακοπὴν οὐ βραχεῖαν ἐργάζονται τοῖς ζηλωταῖς τῶν ὁμοίων ἐπιτηδευμάτων.", "st": "42"}, {"sp": "N", "t": "Ἀλλὰ γὰρ ἔνιοι τὰς Συβαριτῶν καὶ τὰς ἔτι λαγνιστέρων ἐπιθυμίας ζηλώσαντες τὸ μὲν πρῶτον ὀψοφαγίαις καὶ οἰνοφλυγίαις καὶ ταῖς ἄλλαις ταῖς γαστρὸς καὶ τῶν μετὰ γαστέρα ἡδοναῖς ἐνησκήθησαν, εἶτα δὲ κορεσθέντες ἐξύβρισαν — ὕβριν γὰρ κόρος γεννᾶν πέφυκεν —, ὡς ὑπὸ φρενοβλαβείας λυττᾶν καὶ ἐπιμεμηνέναι μηκέτ’ ἀνθρώποις εἴτ’ ἄρρεσιν εἴτε θηλείαις ἀλλὰ καὶ ἀλόγοις ζῴοις, ὥσπερ ἐν Κρήτῃ φασὶ τὸ παλαιὸν τὴν γυναῖκα Μίνω τοῦ βασιλέως ὄνομα Πασιφάην·", "st": "43"}, {"sp": "N", "t": "ταύρου γὰρ ἐρασθεῖσαν καὶ τῷ πάθει σφαδᾴζουσαν ἕνεκα τῆς περὶ τὴν ὁμιλίαν ἀπογνώσεως — ἀποτυγχανόμενος γὰρ ἔρως οὐ μετρίως ἐπιτείνεται — Δαιδάλῳ τὴν κατέχουσαν συμφορὰν ἀνενεγκεῖν, ὃς ἦν τῶν κατ’ αὐτὸν ἄριστος δημιουργός· τὸν δὲ πάνυ δεινὸν ὄντα ταῖς ἐπινοίαις τὰ ἀθήρατα θηρᾶν δούρειον κατασκευάσαι βοῦν καὶ διὰ τῆς ἑτέρας πλευρᾶς ἐνθεῖναι τὴν Πασιφάην, τὸν δὲ ταῦρον ὁρμήσαντα ὡς ἐπὶ ζῷον συγγενὲς ἐπιβαίνειν· ἐγκύμονα δὲ γενομένην χρόνοις ὕστερον ἀποτεκεῖν μιξόθηρα τὸν ἐπικαλούμενον Μινώταυρον.", "st": "44"}, {"sp": "N", "t": "εἰκὸς δὲ καὶ ἄλλας ἔσεσθαι Πασιφάας, ἀχαλινώτων ἐωμένων τῶν παθῶν, καὶ οὐ γυναῖκας μόνον ἀλλὰ καὶ ἄνδρας ἐπιμανήσεσθαι θηρίοις, ἐξ ὧν γενήσεσθαι τέρατα παλίμφημα, μηνύματα τῆς ἀνθρώπων ὑπερβαλλούσης βδελυρίας· δι’ ἣν ἴσως καὶ αἱ τῶν ἀνυπάρκτων καὶ μεμυθευμένων ἀγένητοι φύσεις Ἱπποκενταύρων καὶ Χιμαιρῶν καὶ τῶν ὁμοιοτρόπων ἔσονται.", "st": "45"}, {"sp": "N", "t": "τοσοῦτον δ’ ἄρα τὸ προμηθὲς ἐν τοῖς ἱεροῖς νόμοις ἐστίν, ὥσθ’ ὑπὲρ τοῦ μηδεμίαν ἔκθεσμον ὁμιλίαν ἀνθρώπους προσίεσθαι διείρηται μηδὲ κτῆνος ἐᾶν ὑπό τινος ἑτερογενοῦς ὀχεύεσθαι· τράγον οὐδεὶς ἐάσει ποιμὴν Ἰουδαῖος ἐπιβαίνειν ἀμνάδι οὐδὲ κριὸν χιμαίρᾳ οὐδὲ βοῦν ἵππῳ, εἰ δὲ μή, δώσει δίκας ὡς φύσεως δόγμα λύων, ᾗ τὰ ἀνωτάτω γένη διατηρεῖν ἐπιμελὲς οὐ νοθευόμενα.", "st": "46"}, {"sp": "N", "t": "τοὺς ὀρεῖς ἔνιοι μὲν ἁπάντων ὑποζυγίων προτιμῶσιν, ἐπειδὴ τὰ σώματα αὐτοῖς πέπηγε καὶ σφόδρα νενεύρωται, κἀν τοῖς ἱπποφορβίοις καὶ ταῖς ἱπποστάσεσιν ὄνους ὑπερμεγέθεις, οὓς προσαγορεύουσι κήλωνας, ἀνατρέφουσιν, ἵνα ταῖς θηλείαις ἐπιβαίνωσι πώλοις, αἳ δὴ μικτὸν ζῷον ἀποτίκτουσιν ἡμίονον, ἧς παρὰ φύσιν τὴν γένεσιν εἰδὼς ἀνὰ κράτος ἀπεῖπε Μωυσῆς καθολικωτέρᾳ προστάξει, τοῖς ἀνομοιογενέσι μὴ ἐφεὶς ὀχεύειν ἢ ὀχεύεσθαι.", "st": "47"}, {"sp": "N", "t": "προὐνόησε μὲν οὖν ἀναλόγως τοῦ πρέποντος καὶ ἀκολούθου τῇ φύσει, μακρόθεν δ’ ὡς ἀπὸ σκοπῆς ἐσωφρόνισεν ἀνθρώπους, ἵν’ ἐκ τῶνδε προμαθόντες ἄνδρες ὁμοῦ καὶ γυναῖκες ἀνέχωσιν ὁμιλιῶν ἐκνόμων.", "st": "48"}, {"sp": "N", "t": "ἐάν τε οὖν ἀνὴρ ὀχεύῃ τετράπουν ἐάν τε γυνὴ ὑπὸ τετράποδος ὀχεύηται, θνῃσκέτωσαν καὶ οἱ ἄνθρωποι καὶ τὰ τετράποδα, οἱ μὲν ὅτι ὑπὲρ τοὺς ὅρους ἀκρασίας αὐτῆς ἤλασαν εὑρεταὶ γενόμενοι παρηλλαγμένων ἐπιθυμιῶν καὶ ὅτι ἡδονὰς ἀηδεστάτας ἐκαινούργησαν, ὧν καὶ ἡ διήγησις αἰσχίστη, τὰ δὲ ὅτι τοιούτοις ὀνείδεσιν ὑπηρέτησε καὶ ἵνα μηδὲν ἢ τέκῃ ἢ γεννήσῃ παλίμφημον, οἷα εἰκὸς ἐκ τοιούτων μιασμάτων·", "st": "49"}, {"sp": "N", "t": "ἄλλως τε οἷς καὶ βραχὺ μέλει τοῦ πρέποντος οὐκέτ’ ἂν χρήσαιντο τοῖς θρέμμασιν εἰς οὐδεμίαν τῶν περὶ βίον ὑπηρεσίαν, μυσαττόμενοι καὶ ἀποστρεφόμενοι καὶ τὴν ὄψιν αὐτὴν δυσχεραίνοντες καὶ νομίζοντες ὧν ἂν προσάψαιτο κἀκεῖνα εὐθὺς ἀκάθαρτα εἶναι· τὰ δὲ μηδαμῇ χρήσιμα τῷ βίῳ ζῆν εἰ καὶ λυσιτελὲς ἀλλ’ οὖν περιττὸν “ἄχθος γῆς”, ὡς εἶπέ τις.", "st": "50"}, {"sp": "N", "t": "Πάλιν πόρνην ἡ κατὰ Μωυσῆν οὐ παραδέχεται πολιτεία κοσμιότητος καὶ αἰδοῦς καὶ σωφροσύνης καὶ τῶν ἄλλων ἀρετῶν ἀλλοτρίαν, ἣ ἀναπιμπλᾶσα τὰς ψυχὰς ἀνδρῶν ὁμοῦ καὶ γυναικῶν ἀκολασίας τὸ μὲν τῆς διανοίας ἀθάνατον κάλλος αἰσχύνει, τὴν δὲ τοῦ σώματος ὀλιγοχρόνιον εὐμορφίαν προτιμᾷ, παραρριπτοῦσα μὲν αὑτὴν τοῖς ἐπιτυχοῦσι, τὴν δ’ ὥραν ὥσπερ τι τῶν ὠνίων ἐπ’ ἀγορᾶς πιπράσκουσα, καὶ ἐπὶ μὲν θήρᾳ τῶν νέων ἕκαστα λέγει τε καὶ πράττει, τοὺς δὲ ἐραστὰς ἀλείφει κατὰ ἀλλήλων αἴσχιστον ἆθλον αὑτὴν προτιθεῖσα τοῖς τὸ πλέον εἰσενεγκοῦσιν. ὡς λύμη καὶ ζημία καὶ κοινὸν μίασμα καταλευέσθω, τὰς τῆς φύσεως διαφθείρασα χάριτας, ἃς ἥρμοττε καλοκἀγαθίᾳ προσεπικοσμῆσαι.", "st": "51"}, {"sp": "N", "t": "Μοιχείας δὲ τὰς μὲν ἢ αὐτοφώρους ἢ ἐναργέσιν ἐλέγχοις πιστουμένας ὑπαιτίους ἀπέφηνεν ὁ νόμος, τὰς δὲ καθ’ ὑπόνοιαν οὐκ ἐδικαίωσεν ἐξετάζεσθαι πρὸς ἀνθρώπων, ἀλλὰ εἰς τὸ τῆς φύσεως ἤγαγε δικαστήριον, ἐπειδήπερ ἄνθρωποι μὲν τῶν ἐμφανῶν ἐπιγνώμονες, θεὸς δὲ καὶ τῶν ἀδήλων, ᾧ μόνῳ δυνατὸν ψυχὴν ἐναργῶς θεάσασθαι.", "st": "52"}, {"sp": "N", "t": "φησὶν οὖν τῷ ὑπονοήσαντι ἀνδρί· γραψάμενος πρόκλησιν εἰς τὴν ἱερόπολιν ἴθι σὺν τῇ γυναικὶ καὶ καταστὰς ἐπὶ τῶν δικαστῶν ἀπογύμνωσον τὸ παραστάν σοι τῆς ὑπονοίας πάθος, μὴ ὡς ἄν τις συκοφάντης ἢ κακοτεχνῶν ὑπὲρ τοῦ πάντως περιγενέσθαι, ἀλλ’ ὡς ἄν τις τῆς ἀληθείας ἀκριβὴς ἐξεταστὴς ἄνευ σοφιστείας.", "st": "53"}, {"sp": "N", "t": "ἡ δὲ γυνὴ δύο κινδύνους ὑπομένουσα, τὸν μὲν ὑπὲρ ψυχῆς, τὸν δὲ αἰσχύνης βίου, παντὸς ἀργαλεώτερον θανάτου, κρινάτω παρ’ αὑτῇ τὸ πρᾶγμα, κἂν μὲν καθαρεύῃ, θαρροῦσα ἀπολογείσθω, εἰ δὲ ὑπὸ τοῦ συνειδότος ἐλέγχοιτο, καταδυέσθω, προκάλυμμα τῶν ἁμαρτημάτων αἰδῶ ποιησαμένη· τὸ γὰρ μέχρι τέλους ἀναισχυντεῖν ὑπερβολὴ κακίας.", "st": "54"}, {"sp": "N", "t": "ἐὰν δὲ ἀμφήριστα ᾖ τὰ λεχθέντα καὶ μηδέτερον καθέλκῃ μέρος, ἴτωσαν εἰς τὸ ἱερόν, καὶ ὁ μὲν ἀνὴρ στὰς ἀντικρὺ τοῦ βωμοῦ, παρόντος τοῦ κατ’ ἐκείνην τὴν ἡμέραν ἱερωμένου, δηλούτω τὴν ὑπόνοιαν, ἅμα καὶ κομίζων ἄλευρον κρίθινον, εἶδός τι θυσίας ὑπὲρ τῆς γυναικός, εἰς ἔνδειξιν τοῦ μὴ κατ’ ἐπήρειαν ἀλλ’ ἀπὸ γνώμης ὑγιοῦς κατ’ ἐνδοιασμὸν εὔλογον αἰτιᾶσθαι.", "st": "55"}, {"sp": "N", "t": "ὁ δὲ ἱερεὺς λαβὼν προτεινέτω τῇ γυναικὶ καὶ τοὐπίκρανον ἀφελών, ἵν’ ἐπικρίνηται γεγυμνωμένῃ τῇ κεφαλῇ, τὸ τῆς αἰδοῦς περιῃρημένη σύμβολον, ᾧ ταῖς εἰς ἅπαν ἀναιτίοις ἔθος χρῆσθαι. μήτε δὲ ἔλαιον μήτε λιβανωτὸς ὡς ἐπὶ τῶν ἄλλων θυσιῶν παρέστω, διὰ τὸ μὴ ἐπὶ χαρτοῖς ἀλλ’ ἄγαν ὀδυνηροῖς τὴν θυσίαν μέλλειν ἐπιτελεῖσθαι.", "st": "56"}, {"sp": "N", "t": "κρίθινον δ’ ἐστὶ τὸ ἄλευρον, ἴσως ἐπειδὴ ὑπαμφίβολός ἐστιν ἡ ἀπὸ κριθῆς τροφὴ καὶ ἀλόγοις ζῴοις καὶ ἀτυχέσιν ἀνθρώποις ἐφαρμόζεται, σύμβολον τοῦ τὴν μεμοιχευμένην οὐδὲν θηρίων διαφέρειν, ὧν ἀδιακρίτους εἶναι καὶ ἀνεπιστάτους τὰς ὀχείας συμβέβηκε, τὴν δὲ καθαρεύουσαν τῶν ἐγκλημάτων τὸν οἰκεῖον ἀνθρώπων βίον ἐζηλωκέναι.", "st": "57"}, {"sp": "N", "t": "λαβὼν δέ, φησίν, ὁ ἱερεὺς κεραμεοῦν ἀγγεῖον ἐγχείτω καθαρὸν ὕδωρ ἐκ πηγῆς ἀρυσάμενος καὶ ἐπιφερέτω βῶλον γῆς ἐκ τοῦ κατὰ τὸ ἱερὸν ἐδάφους· ἅπερ οἶμαι καὶ αὐτὰ συντείνειν πρὸς τὴν ἔρευναν τῆς ἀληθείας διὰ συμβόλων, τὸ μὲν κεραμεοῦν ἀγγεῖον πρὸς τὸ μεμοιχεῦσθαι, διὰ τὸ εὐκάτακτον, θάνατος γὰρ ἡ κατὰ μοιχῶν δίκη, ἡ δὲ γῆ καὶ τὸ ὕδωρ πρὸς τὸ καθαρεύειν τῆς αἰτίας, ἐπειδὴ δι’ ἀμφοτέρων αἱ γενέσεις καὶ αὐξήσεις καὶ τελειώσεις ἁπάντων.", "st": "58"}, {"sp": "N", "t": "ὅθεν ἑκάτερον οὐκ ἀπὸ σκοποῦ καὶ τοῖς ὀνόμασιν ἐπεκόσμησε, τὸ μὲν ὕδωρ εἰπὼν δεῖν “καθαρὸν” λαμβάνειν καὶ “ζῶν”, ἐπεὶ ἀνυπαίτιος ἡ γυνὴ καθαρεύει τὸν βίον καὶ ζῆν ὀφείλει, τὴν δὲ γῆν οὐκ ἀπὸ τοῦ τυχόντος ἀλλ’ ἀπὸ τοῦ ἱεροῦ ἐδάφους, ὅπερ ἀναγκαῖον ἀρετᾶν, ὡς καὶ γυναῖκα τὴν σώφρονα.", "st": "59"}, {"sp": "N", "t": "τούτων δὲ προευτρεπισθέντων, ἡ μὲν ἀκατακαλύπτῳ τῇ κεφαλῇ τὸ κρίθινον ἄλευρον κομίζουσα, καθάπερ ἐλέχθη, παρίτω, ὁ δὲ ἱερεὺς [ἀντικρὺ] τὸ κεραμεοῦν ἀγγεῖον, ἐν ᾧ ὕδωρ ἐστὶ καὶ γῆ, ἀντικρὺ στὰς ἐπιλεγέτω τάδε·", "st": "60"}, {"sp": "N", "t": "“εἰ μὲν τοὺς ἐπὶ γάμοις θεσμοὺς οὐ παραβέβηκας οὐδ’ ἀνὴρ ἕτερος ὡμίλησέ σοι καθυφεμένῃ τὰ πρὸς τὸν νόμῳ συνοικισθέντα δίκαια, ἀνυπαίτιος καὶ ἀθῷος ἴσθι· εἰ δ’ ὠλιγώρησας μὲν ἀνδρὸς καινὰς δὲ ἐζήλωσας ἐπιθυμίας ἢ ἐρασθεῖσα ἢ ἐρασθέντι ἐνδοῦσα, τὰ ἀναγκαιότατα καὶ φίλτατα προδοῦσα καὶ νοθεύσασα, μὴ ἀγνόει πάσαις ἀραῖς ἔνοχος γεγενημένη, ὧν τὰ δείγματα ἀναφανεῖς ἐπὶ τοῦ σώματος.", "st": "61"}, {"sp": "N", "t": "ἴθι δὴ ἔκπινε ποτὸν ἐλέγχου, ὃ τὰ κεκρυμμένα νῦν καὶ ἀδηλούμενα ἀπαμφιάσει καὶ ἀπογυμνώσει.” ταῦτα γράψας ἐν χαρτιδίῳ καὶ ἀπαλείψας τῷ κατὰ τὸ ἀγγεῖον ὕδατι προτεινέτω τῇ γυναικί· ἡ δὲ πιοῦσα ἀπαλλαττέσθω προσδοκῶσα ἢ σωφροσύνης ἆθλον ἢ ἀκολασίας τὴν ἀνωτάτω τιμωρίαν. εἰ μὲν γὰρ σεσυκοφάντηται, σπορὰν καὶ γένεσιν τέκνων ἐλπιζέτω τῶν ἐπὶ στειρώσει καὶ ἀγονίᾳ φόβων καὶ φροντίδων ἀλογοῦσα· εἰ δ’ ἐστὶν ἔνοχος, ἐφεδρεύσοντα ἴστω γαστρὸς ὄγκον οἰδούσης καὶ πιμπραμένης καὶ τῶν περὶ μήτραν δεινὴν κάκωσιν, ἣν καθαρὰν οὐκ ἠξίωσε διατηρεῖν ἀνδρὶ τῷ κατὰ πάτρια γήμαντι.", "st": "62"}, {"sp": "N", "t": "τοσαύτην δ’ ἔχει πρόνοιαν ὁ νόμος τοῦ μηδὲν ἐπὶ γάμοις νεωτερίζεσθαι, ὥστε καὶ τοὺς συνιόντας εἰς ὁμιλίαν ἄνδρας καὶ γυναῖκας κατὰ τοὺς ἐπὶ γάμοις θεσμούς, ὅταν εὐνῆς ἀπαλλάττωνται, οὐ πρότερον ἐᾷ τινος ψαύειν ἢ λουτροῖς καὶ περιρραντηρίοις χρῆσθαι, πόρρωθεν μοιχείας ἀνείργων καὶ τῶν ἐπὶ μοιχείαις ἐγκλημάτων.", "st": "63"}, {"sp": "N", "t": "Ἐὰν δέ τις χήραν ἀποθανόντος ἀνδρὸς ἢ καὶ διαζευχθεῖσαν ἄλλως βιασάμενος αἰσχύνῃ, κουφότερον ἢ κατὰ μοιχείαν ἁμάρτημα δρῶν, ἥμισυ σχεδὸν ἐκείνου, τῆς μὲν θανάτου τιμωρίας ἀφείσθω, βίαν δὲ καὶ ὕβριν καὶ ἀκολασίαν καὶ θράσος τὰ αἴσχιστα ὡς κάλλιστα ἀποδεξάμενος κατηγορείσθω καὶ ὅ τι χρὴ παθεῖν ἢ ἀποτῖσαι τιμάτω τὸ δικαστήριον ἐπ’ αὐτῷ.", "st": "64"}, {"sp": "N", "t": "Ἀδελφὸν μὲν καὶ συγγενὲς ἀδίκημα μοιχείας φθορά, καθάπερ ἐκ μητρὸς μιᾶς, ἀκολασίας, φύντα· ἣν ἔνιοι τῶν εἰωθότων εὐπρεπέσιν ὀνόμασι τὰ αἰσχρὰ ἐπικοσμεῖν ἔρωτα ὀνομάζουσι τἀληθὲς ὁμολογεῖν ἐρυθριῶντες. ἀλλ’ ὅμως, εἰ καὶ συγγενές, οὐ παντάπασιν ὅμοιον, τῷ τὸ ἀδίκημα μὴ εἰς πλείους χωρεῖν οἰκίας, ὡς ἐπὶ τῆς μοιχείας συμβέβηκεν, ἀλλ’ εἰς μίαν συνῆχθαι τὴν τῆς παρθένου.", "st": "65"}, {"sp": "N", "t": "λεκτέον οὖν τῷ κόρης ἀστῆς ἐπιθυμοῦντι· “προπέτειαν καὶ θράσος ἀναίσχυντον ἢ τὰς ἐπ’ ἐνέδρᾳ πάγας ἤ τι τῶν ὁμοιοτρόπων, ὦ οὗτος, ἀποστραφεὶς μήτε ἀναφανδὸν μήτε λάθρα πονηρὸς ἐξετασθῇς.", "st": "66"}, {"sp": "N", "t": "ἀλλ’ εἴπερ ἄρα τι τῇ ψυχῇ πέπονθας πρὸς τὴν παῖδα οἰκεῖον, ἴθι πρὸς τοὺς γονεῖς αὐτῆς, ἐὰν ζῶντες τυγχάνωσιν, εἰ δὲ μή, πρὸς τοὺς ἀδελφοὺς ἢ ἐπιτρόπους ἢ ἄλλους κυρίους, καὶ ἀπογυμνώσας τὸ σεαυτοῦ πάθος, ὡς χρὴ τὸν ἐλεύθερον, αἴτει πρὸς γάμον καὶ παρακάλει μὴ ἀνάξιος νομισθῆναι.", "st": "67"}, {"sp": "N", "t": "σκαιὸς γὰρ οὐδεὶς ἂν οὕτως γένοιτο τῶν ἐπιμελουμένων τῆς παιδός, ὡς ἐναντιωθῆναι πρὸς λιπαρεστέρας δεήσεις, καὶ μάλιστά γε ἐπειδὰν ἐξετάσας ἀνευρίσκῃ μὴ κατεψευσμένον ἢ ἐπιπόλαιον ἄλλως τὸ πάθος ἀλλ’ ἐπαληθεῦον καὶ παγίως ἐνιδρυμένον.”", "st": "68"}, {"sp": "N", "t": "ἐὰν δέ τις λυττῶν καὶ μεμηνώς, ἅπασι τοῖς ἐκ λογισμοῦ πολλὰ χαίρειν φράσας, δυναστείαν τὸν οἶστρον καὶ τὴν ἐπιθυμίαν ὑπολαβών, νόμου βίαν, ὥς φασί τινες, προτιμοτέραν θέμενος, ἁρπάζῃ καὶ φθείρῃ ταῖς ἐλευθέραις ὡς θεραπαίναις χρώμενος, τὰ πολέμου δρῶν ἐν εἰρήνῃ, πρὸς τοὺς δικαστὰς ἀγέσθω.", "st": "69"}, {"sp": "N", "t": "κἂν μὲν ᾖ πατὴρ τῇ βιασθείσῃ, βουλευέσθω περὶ ἐγγύης τῆς πρὸς τὸν ἐφθαρκότα· εἶτα ἐὰν μὲν ἀνανεύῃ, προικιζέτω τὴν παῖδα ὁ φθορεὺς ἄλλως ζημιούμενος χρήμασιν, ἐὰν δὲ συναινῇ καὶ συνεπιγράφηται, μηδὲν ὑπερτιθέμενος ἀγέσθω προῖκα πάλιν τὴν ἴσην ὁμολογῶν καὶ μήτε ἀναδύεσθαι τὴν ἐξουσίαν ἐχέτω μήτε παραιτεῖσθαι, καὶ δι’ αὐτόν, ἵνα μὴ λαγνείας ἕνεκα δοκῇ μᾶλλον ἢ κατ’ ἔρωτα νόμιμον ἐφθαρκέναι, καὶ διὰ τὴν κόρην, ἵν’ αὐτῆς τὸ περὶ τὴν πρώτην σύνοδον ἀτύχημα παρηγορηθῇ βεβαιοτάτῳ γάμῳ, ὃν οὐδὲν ἄλλο τι ἢ θάνατος διαζεύξει.", "st": "70"}, {"sp": "N", "t": "ἐὰν δὲ πατρὸς ὀρφανὴ τυγχάνῃ, πρὸς τῶν δικαστῶν ἐρωτάσθω, εἴτε βούλεται συνοικεῖν εἴτε μή· ἐάν τε δὲ συναινῇ ἐάν τε ἀρνῆται, τὰ αὐτὰ γινέσθω ἃ ἂν καὶ ἐπὶ ζῶντι διωμολογήθη τῷ πατρί.", "st": "71"}, {"sp": "N", "t": "Μεθόριόν τινες ὑπολαμβάνουσιν ἀδίκημα εἶναι φθορᾶς καὶ μοιχείας ὑπογάμιον, ὅταν ὁμολογίαι μὲν ὑπερεγγυήσωσι, μήπω δὲ τῶν γάμων ἐπιτελεσθέντων ἕτερος ἀπατήσας τις ἢ καὶ βιασάμενος εἰς ὁμιλίαν ἔλθῃ. παρ’ ἐμοὶ δὲ κριτῇ μοιχείας καὶ τοῦτ’ ἐστὶν εἶδος· αἱ γὰρ ὁμολογίαι γάμοις ἰσοδυναμοῦσιν, αἷς ἀνδρὸς ὄνομα καὶ γυναικὸς καὶ τὰ ἄλλα τὰ ἐπὶ συνόδοις ἐγγράφεται.", "st": "72"}, {"sp": "N", "t": "ὧν χάριν καταλεύειν ὁ νόμος ἀμφοτέρους προσέταξεν, ἐάν γε ἀπὸ μιᾶς καὶ τῆς αὐτῆς γνώμης ἐπιθῶνται τοῖς ἀδικήμασι συμφρονήσαντες· οὐχ οἷόν τε γὰρ μὴ ἀπὸ τῶν αὐτῶν ὁρμηθέντας βουλευμάτων νομίζεσθαι συναδικεῖν, οὐ συναδικοῦντας.", "st": "73"}, {"sp": "N", "t": "παρὰ γοῦν τὰς τῶν τόπων διαφορὰς αὔξεσθαι συμβέβηκε καὶ μειοῦσθαι τἀδίκημα· μεῖζον μὲν γάρ, ὡς εἰκός, ἐστίν, εἰ πραχθείη κατὰ πόλιν, ἔλαττον δέ, εἰ τειχῶν ἔξω κατ’ ἐρημίαν· ἐνταῦθα μὲν γὰρ βοηθὸς οὐδὲ εἷς ἐστι τῇ παιδὶ πάνθ’ ὅσα ὑπὲρ τοῦ διατηρῆσαι τὴν παρθενίαν ἄψαυστον καὶ ἀνεπιβούλευτον λεγούσῃ τε καὶ δρώσῃ, ἐν ἄστει δὲ βουλευτήρια, δικαστήρια, στρατηγῶν, ἀγορανόμων, ἀστυνόμων, ἄλλων ἀρχόντων ὅμιλοι μεγάλοι καὶ σὺν τούτοις ὁ δῆμος.", "st": "74"}, {"sp": "N", "t": "ἔστι γὰρ ἔστιν ἐν ἑκάστου τῇ ψυχῇ, κἂν ἰδιώτης τυγχάνῃ, μισοπόνηρον πάθος, ὃ διακινηθὲν ἀποδείκνυσι τὸν ἔχοντα κατ’ ἐκεῖνον τὸν χρόνον ὑπέρμαχον καὶ προαγωνιστὴν αὐτοκέλευστον τοῦ δόξαντος ἠδικῆσθαι.", "st": "75"}, {"sp": "N", "t": "τῷ μὲν οὖν διαπραξαμένῳ τὴν βίαν ἕπεται δίκη πανταχοῦ, μηδὲν ἐκ τῆς τῶν χωρίων διαφορᾶς εὑρισκομένῳ πρὸς ἐπανόρθωσιν ὧν ὕβρισε καὶ παρηνόμησε· τῇ δὲ παιδί, καθάπερ ἔφην, τοτὲ μὲν ἔλεος καὶ συγγνώμη τοτὲ δὲ ἀπαραίτητος τιμωρία παρακολουθήσει.", "st": "76"}, {"sp": "N", "t": "καὶ περὶ ταύτης μέντοι πολυπραγμονητέον τῷ δικαστῇ μὴ πάντ’ ἐπὶ τοὺς τόπους ἀναφέροντι· δύναται γὰρ καὶ κατὰ μέσην τὴν πόλιν ἄκουσα βεβιάσθαι καὶ ἔξω τῆς πόλεως ἑκοῦσα πρὸς ἔκθεσμον ὁμιλίαν ἐνδοῦναι. διὸ παρατετηρημένως καὶ σφόδρα καλῶς ἀπολογούμενος ὑπὲρ τῆς ἐν ἐρημίᾳ φθειρομένης φησὶν ὁ νόμος· “ἐβόησεν ἡ νεᾶνις, καὶ ὁ βοηθήσων οὐκ ἦν αὐτῇ”, ὥστε, εἰ μήτε ἐβόησε μήτε ἠναντιώθη, βουλομένη δὲ συναπῆρε, γένοιτ’ ἂν ἔνοχος, σόφισμα τοῦ βεβιάσθαι δοκεῖν προστησαμένη τὸν τόπον.", "st": "77"}, {"sp": "N", "t": "καὶ μὴν ἐν πόλει τί γένοιτ’ ἂν ὄφελος τῇ πάντα μὲν ἐθελούσῃ ποιεῖν ὑπὲρ τῆς ἰδίας ἐπιτιμίας, ἀδυνατούσῃ δὲ ἕνεκα τῆς περὶ τὸν ὑβριστὴν ἰσχύος; τί γὰρ, εἰ μετὰ τῶν ἄλλων καταδήσειεν ἢ τὸ στόμα ἀποφράξειεν, ὡς μηδὲ φωνὴν ῥῆξαι δύνασθαι, γένοιτ’ ἂν ὄφελος ἐκ τῶν συνοικούντων; τρόπον γάρ τινα ἥδε μὲν ἐν πόλει διατρίβουσα κατ’ ἐρημίαν ἐστὶν ἅτε βοηθῶν ἔρημος, ἡ δέ, κἂν μηδεὶς παρατυγχάνῃ, τῷ ἑκοῦσα συναπᾶραι λέγοιτ’ ἂν οὐδὲν διαφέρειν τῆς ἐν ἄστει.", "st": "78"}, {"sp": "N", "t": "Εἰσὶ δέ τινες περὶ τὰς ὁμιλίας ἁψίκοροι, γυναικομανεῖς ἐν ταὐτῷ καὶ μισογύναιοι, συγκλύδων καὶ μιγάδων ἠθῶν ἀνάπλεῳ, οἳ ταῖς πρώταις εὐθὺς ὁρμαῖς ἐνδιδόντες, ὁποῖαί περ ἂν οὖσαι τυγχάνωσιν, ἃς ἡνιοχεῖν δέον ἀχαλινώτους ἐῶσιν, ἀπερισκέπτως καὶ ἀπροοράτως σώμασιν ὁμοῦ καὶ πράγμασιν ἐπεμπίπτοντες τυφλῶν τρόπον, ἅτε ῥύμῃ καὶ φορᾷ βιαίῳ συνωθοῦντες καὶ ἀνατρέποντες, οὐκ ἐλάττω ὧν διατιθέασι πάσχουσι.", "st": "79"}, {"sp": "N", "t": "περὶ ὧν τάδε νομοθετεῖται· κόρας οἱ ἀγόμενοι νόμῳ καὶ γάμους θύσαντές τε καὶ ἑστιαθέντες, μηδὲν οἰκεῖον ἐπὶ ταῖς γαμεταῖς πάθος σῴζοντες, ἀλλ’ ὑβρίσαντες καὶ ὡς ἑταίραις ταῖς ἀσταῖς προσενεχθέντες, ἐὰν διάζευξιν τεχνάζωσι μηδεμίαν ἀπαλλαγῆς πρόφασιν ἀνευρίσκοντες, εἶτ’ ἐπὶ τὸ συκοφαντεῖν τραπόμενοι σπάνει φανερῶν ἐγκλημάτων πρὸς τὰ ἀφανῆ τρέπωσι τὰς αἰτίας καὶ παρελθόντες κατηγορῶσιν, ὅτι παρθένοις δόξαντες συνεληλυθέναι γυναῖκας ἐν ταῖς πρώταις ὁμιλίαις ἐφώρασαν, ἀθροιζέσθω μὲν ἡ γερουσία πᾶσα πρὸς τὴν κρίσιν, παρίτωσαν δὲ οἱ τῶν κατηγορουμένων γονεῖς ἀπολογησόμενοι περὶ κοινοῦ κινδύνου.", "st": "80"}, {"sp": "N", "t": "κίνδυνος γὰρ οὐ ταῖς θυγατράσι μόνον περὶ τῆς τῶν σωμάτων ἁγνείας ἐστίν, ἀλλὰ καὶ τοῖς ἐπιμεληταῖς, οὐ μόνον ὅτι εἰς τὸν ἀναγκαιότατον τῆς ἀκμῆς καιρὸν οὐ παρετήρησαν, ἀλλ’ ὅτι καὶ ὡς παρθένους τὰς ὑφ’ ἑτέρων ἐφθαρμένας ἐνεγύησαν ἀπατῶντες καὶ φενακίζοντες τοὺς λαμβάνοντας.", "st": "81"}, {"sp": "N", "t": "εἶτα ἐὰν περιγένωνται τοῖς δικαίοις, τιμάτωσαν οἱ δικασταὶ κατὰ τῶν ψευδεῖς αἰτίας πλαττομένων χρημάτων ζημίας καὶ τὰς διὰ πληγῶν εἰς τὰ σώματα ὕβρεις καὶ—τὸ πάντων ἐκείνοις ἀηδέστατον—τὴν τῶν γάμων βεβαίωσιν, ἐὰν ὑπομένωσιν αἱ γυναῖκες ἔτι τοῖς τοιούτοις συνοικεῖν· ταῖς μὲν γὰρ ἐφίησιν ὁ νόμος θελούσαις καὶ μένειν καὶ ἀπαλλάττεσθαι, τοὺς δὲ οὐδετέρου κυρίους ἀπέφηνεν, ἀνθ’ ὧν ἐσυκοφάντησαν.", "st": "82"}, {"sp": "N", "t": "Ὄνομα μὲν ἀνδροφονία κατὰ τοῦ κτείναντος ἄνθρωπον ἐπιφημίζεται, τὸ δ’ ἀληθὲς ἔργον ἐστὶν ἱεροσυλία καὶ ἱεροσυλιῶν ἡ μεγίστη, διότι τῶν ἐν κόσμῳ κτημάτων καὶ κειμηλίων οὐδὲν οὔτε ἱεροπρεπέστερον οὔτε θεοειδέστερόν ἐστιν ἀνθρώπου· * * *", "st": "83"}, {"sp": "N", "t": "παγκάλης εἰκόνος πάγκαλον ἐκμαγεῖον ἀρχετύπου λογικῆς ἰδέας παραδείγματι τυπωθέν. τὸν οὖν ἀνδροφόνον εὐθὺς ἀσεβῆ καὶ ἀνοσιουργὸν ὑποληπτέον, ἀνοσιουργημάτων καὶ ἀσεβημάτων δρῶντα τὸ μέγιστον, ὃν ἀμείλικτα ἐργασάμενον ἀναιρετέον, ἐπειδὴ μυρίων θανάτων ἐπάξιος ὢν ἕνα ὑπομένει διὰ τὸ τῆς τιμωρίας ἀθάνατον εἰς πλῆθος μὴ πεφυκυίας συναύξεσθαι· χαλεπὸν δὲ οὐδέν, εἰ ταὐτὸν οἷς διέθηκέ τις πείσεται.", "st": "84"}, {"sp": "N", "t": "καίτοι πῶς ἐστι ταὐτόν, εἰ καὶ χρόνοις καὶ πράξεσι καὶ βουλήμασι καὶ προσώποις διαλλάττει; ἢ οὐχὶ τὸ μὲν χειρῶν ἄρχειν ἀδίκων ἐστὶ πρότερον, τὸ δ’ ἀμύνεσθαι ὕστερον; καὶ ἀνδροφονία μὲν παρανομώτατον, ἡ δὲ κατὰ ἀνδροφόνων κόλασις νομιμώτατον; καὶ ὁ μὲν κτείνας ἐκπεπλήρωκε τὴν ἐπιθυμίαν ὃν προῄρητο ἀνελών, ὁ δὲ πεπονθὼς ἅτε γεγονὼς ἐκποδὼν οὔτ’ ἀντιδιαθεῖναι οὔτ’ ἀντεφησθῆναι δυνατός ἐστι; καὶ ὁ μὲν ἐπιβουλεύειν αὐτοχειρίᾳ πέφυκε δι’ ἑαυτοῦ, τῷ δ’ ἀτελὴς ἡ ἐπέξοδος, εἰ μὴ συγγενεῖς ἢ φίλοι προαγωνίσαιντο λαβόντες τοῦ πάθους οἶκτον;", "st": "85"}, {"sp": "N", "t": "Ἐάν τις ἐπανατείνηται ξίφος, ὥστε ἀποκτεῖναι, κἂν μὴ ἀνέλῃ, ἔνοχος ἔστω προαιρέσει γεγονὼς ἀνδροφόνος, εἰ καὶ μὴ τὸ τέλος τῇ γνώμῃ συνέδραμε. τὰ δ’ αὐτὰ πασχέτω, κἂν σὺν τέχνῃ τις ἐξ ἐνέδρας, οὐ θαρρῶν ἄντικρυς ἐπιχειρεῖν, βουλεύῃ καὶ μηχανᾶται δολερῶς τὸν φόνον· ἐναγὴς γὰρ καὶ οὗτος εἰ καὶ μήπω ταῖς χερσὶν ἀλλά τοι τῇ", "st": "86"}, {"sp": "N", "t": "ψυχῇ καθέστηκεν. ὥσπερ γάρ, οἶμαι, πολεμίους οὐ μόνον τοὺς ἤδη ναυμαχοῦντας ἢ πεζομαχοῦντας ἀλλὰ καὶ τοὺς εἰς ἑκάτερον παρεσκευασμένους καὶ τὰς ἑλεπόλεις ἐφιστάντας τοῖς λιμέσι καὶ τείχεσι, κἂν μήπω συμπλέκωνται, κρίνομεν, οὕτως καὶ ἀνδροφόνους χρὴ νομίζειν οὐ τοὺς κτείναντας αὐτὸ μόνον ἀλλὰ καὶ τοὺς πάντα δρῶντας εἰς τὸ ἀνελεῖν ἢ φανερῶς ἢ λάθρα, κἂν μὴ τὸ ἀδίκημα ὦσιν εἰργασμένοι.", "st": "87"}, {"sp": "N", "t": "ἐὰν δὲ καὶ ὑπὸ δειλίας ἢ θράσους, μαχομένων καὶ ἐπιλήπτων παθῶν, καταφυγεῖν τολμῶσιν εἰς τὸ ἱερὸν ὡς ἀσυλίαν εὑρησόμενοι, κωλυτέον· κἂν ὀφθῶσι παρεισδύντες, ἐκδοτέον ἐπ’ ἀναιρέσει τοιαῦτα ἐπιλέγοντας, ἀσυλίαν ἀνιέροις τὸ ἱερὸν μὴ παρέχεσθαι. πᾶς γὰρ ὁ ἀνίατα δρῶν ἐχθρὸς θεῷ· ἀνδροφόνοι δὲ ἀνίατα δρῶσιν, ἐπεὶ καὶ οἱ ἀνδροφονηθέντες ἀνίατα πεπόνθασιν.", "st": "88"}, {"sp": "N", "t": "ἢ τοῖς μὲν μηδὲν ἡμαρτηκόσιν, ἕως ἂν ἀπολούσωνται καὶ περιρρανάμενοι καθαρθῶσι τοῖς εἰωθόσι καθαρσίοις, ἄβατος ὁ νεώς ἐστι, τοὺς δὲ ἐνόχους ἀνεκπλύτοις ἄγεσιν, ὧν τὰ μιάσματα οὐδεὶς ἀπονίψει χρόνος, ἄξιον ἐπιφοιτᾶν καὶ ἐνδιατρίβειν τοῖς ἕδεσιν, οὓς οὐδ’ ἂν οἰκία δέξαιτο κοσμίων ἀνδρῶν οἷς μέλει τῶν ὁσίων;", "st": "89"}, {"sp": "N", "t": "προστιθέντας οὖν ἀδικήματα ἀδικήμασιν, ἀνδροφονίᾳ παρανομίαν καὶ ἀσέβειαν, ἀναγκαῖον ἀπάγειν δώσοντας δίκην, τοὺς ὡς ἔφην ἄξια μυρίων θανάτων, οὐχ ἑνός, εἰργασμένους. ἄλλως τε τοῖς συγγενέσι καὶ φίλοις τοῦ δολοφονηθέντος ἀποκεκλείσεται τὸ ἱερόν, εἰ ὁ ἀνδροφόνος ἐνδιατρίβοι, μὴ ἂν ὑπομείνασιν εἰς ταὐτόν ποτε ἐλθεῖν· ἄτοπον δὲ ἑνὸς ἕνεκα πολλοὺς καὶ τοῦ παρανομωτάτου τοὺς παρανομηθέντας ἐξελαύνεσθαι, οἳ πρὸς τῷ μηδὲν ἁμαρτεῖν ἔτι καὶ πένθος πρόωρον ἀνεδέξαντο.", "st": "90"}, {"sp": "N", "t": "τάχα μέντοι καὶ τὰ μακρὰν ὀξυωπίᾳ λογισμοῦ πεφυκὼς ἐμβλέπειν προὐνόησε μὴ φόνον ἐν τῷ ἱερῷ γενέσθαι κατὰ τὰς ἐπιφοιτήσεις τῶν τοῦ σφαγέντος ἐπιτηδείων, οὓς στοργή, πάθος ἀδούλωτον, ὥσπερ τοὺς ἐνθουσιῶντας καὶ κατεχομένους προκαλέσεται μόνον οὐκ αὐτοχειρίᾳ κτεῖναι τὸν ἀνδροφόνον· οὗ γενομένου συμβήσεταί τι τῶν ἀνοσιωτάτων, αἵματι γὰρ ἀνδροφόνων αἷμα θυσιῶν ἀνακραθήσεται, τὸ τῶν καθωσιωμένων τῷ μὴ καθαρῷ. διὰ μὲν δὴ ταῦτα κελεύει καὶ ἀπ’ αὐτῶν τῶν βωμῶν ἐκδοῦναι τὸν ἀνδροφόνον.", "st": "91"}, {"sp": "N", "t": "Ἀλλ’ οἱ μὲν ξίφεσιν ἢ δορατίοις ἢ βέλεσιν ἢ ξύλοις ἢ λίθοις ἤ τισιν ὁμοιοτρόποις ἀναιροῦντες δύνανται μὴ προβεβουλευμένοι μηδ’ ἐκ πολλοῦ παρ’ αὑτοῖς λελογισμένοι τὸ ἄγος, ἐκ ταὐτομάτου διακινηθέντες καὶ θυμῷ δυνατωτέρῳ χρησάμενοι λογισμοῦ, δρᾶσαι τὸν φόνον, ὡς ἡμίεργον τὴν πρᾶξιν εἶναι, τῆς διανοίας μὴ προκατεσχημένης ἐκ μακροῦ τοῖς μιάσμασιν.", "st": "92"}, {"sp": "N", "t": "εἰσὶ δὲ ἕτεροι πονηρότατοι, χερσὶ καὶ γνώμαις ἐναγεῖς, οἱ μάγοι καὶ φαρμακευταί, σχολὴν καὶ ἀναχώρησιν ἐνδιδόντες αὑτοῖς πρὸς καιρίους ἐπιθέσεις καὶ τέχνας καὶ μηχανὰς πολυτρόπους ἀνευρίσκοντες ἐπὶ ταῖς τῶν πλησίον συμφοραῖς.", "st": "93"}, {"sp": "N", "t": "ὅθεν κελεύει φαρμακευτὰς καὶ φαρμακίδας μηδεμίαν ἡμέραν ἀλλὰ μηδ’ ὥραν ἐπιβιοῦν, ἀλλ’ ἅμα τῷ ἁλῶναι τεθνάναι, μηδεμιᾶς ἐγγινομένης προφάσεως εἰς ἀναβολὴν καὶ ὑπέρθεσιν τῆς τιμωρίας· τοὺς μὲν γὰρ ἄντικρυς ἐπιβουλεύοντας δύναιτ’ ἄν τις φυλάξασθαι, τῶν δὲ κρύφα συντιθέντων καὶ σκευωρούντων τὰς ἐπιθέσεις φαρμακείαις οὐ ῥᾴδιον τὰς τέχνας συνιδεῖν.", "st": "94"}, {"sp": "N", "t": "ἀναγκαῖον οὖν, ἃ μελλήσουσι δι’ αὐτοὺς ἕτεροι παθεῖν, τοὺς δρῶντας προδιαθεῖναι. καὶ γὰρ ἄλλως ὁ μὲν ἐμφανῶς ξίφει κτείνων ἤ τινι ὅπλῳ τῶν ὁμοιοτρόπων καθ’ ἕνα καιρὸν ὀλίγους ἀνελεῖ, φαρμάκοις δὲ θανασίμοις μυρίους ὅσους τὴν ἐπιβουλὴν οὐ προαισθανομένους ἐδωδίμοις τισὶν ἀναμίξας καὶ συνανακερασάμενος.", "st": "95"}, {"sp": "N", "t": "ἤδη γοῦν πολυάνθρωπα συσσίτια καθ’ ἑταιρείαν συνεληλυθότων ἐπὶ τοὺς αὐτοὺς ἅλας καὶ τὴν αὐτὴν τράπεζαν ἐν σπονδαῖς ἄσπονδα ἔπαθεν ἐξαίφνης διαφθαρέντα καὶ θάνατον ἀντ’ εὐωχίας ἀντηλλάξατο. διὸ προσήκει κατὰ τῶν τοιούτων καὶ τοὺς ἐπιεικεστάτους καὶ τοὺς μετριοπαθεστάτους φονᾶν, μόνον οὐκ αὐτόχειρας γινομένους καὶ νομίζοντας εὐαγὲς εἶναι τὸ μὴ ἑτέροις τὴν τιμωρίαν ἐπιτρέπειν ἀλλ’ ἑαυτοῖς.", "st": "96"}, {"sp": "N", "t": "πῶς γὰρ οὐκ ἔστι πάνδεινον, διὰ τροφῆς ἣ τοῦ ζῆν αἰτία καθέστηκε θάνατον τεχνάζειν καὶ τοῖς φύσει τροφίμοις φθοροποιὸν ἐνεργάζεσθαι μεταβολήν, ἵνα τινὲς διὰ φυσικὴν ἀνάγκην ἐπ’ ἐδωδὴν καὶ πόσιν ἰόντες, οὐ προϊδόντες τὴν ἐνέδραν, ὡς σωτήρια προσῶνται τὰ πανωλεθρίας αἴτια;", "st": "97"}, {"sp": "N", "t": "τὴν δ’ αὐτὴν ὑπομενέτωσαν τιμωρίαν, κἄν [εἴ] τινες θανάσιμα μὴ συντιθέντες τὰ δι’ ὧν μακραὶ κατασκευάζονται νόσοι προσφέρωσι· θάνατοι γὰρ πολλάκις αἱρετώτεροι νόσων εἰσὶ καὶ μάλιστα τῶν τοιούτων, αἳ μήκεσι χρόνων ἀποτείνονται καὶ τέλος ἔχουσιν οὐκ αἴσιον· δυσίατα γὰρ ἤδη καὶ παντελῶς ἀθεράπευτα τὰ ἐκ φαρμακειῶν ἀρρωστήματα.", "st": "98"}, {"sp": "N", "t": "χαλεπώτερα μέντοι συμβαίνειν φιλεῖ τῶν ἐν τοῖς σώμασι καὶ τὰ περὶ τὰς ψυχὰς πάθη τῶν ἐπιβουλευομένων· ἐκστάσεις γὰρ καὶ παραφροσύναι καὶ ἀφόρητοι μανίαι κατασκήπτουσι, δι’ ὧν ὁ νοῦς, ἣν μεγίστην ἀπένειμεν ἀνθρώπων γένει δωρεὰν ὁ θεός, κακούμενος πάσας κακώσεις, ὅταν ἀπογνῷ τὰ σωτήρια, μετανίσταται καὶ μετοικίζεται τὸ τῆς ψυχῆς φαυλότερον εἶδος ὑπολειπόμενος ἐν τῷ σώματι, τὸ ἄλογον, οὗ καὶ τὰ θηρία μετέσχηκεν, ἐπειδὴ πᾶς ὁ ἐρημωθεὶς λογισμοῦ τοῦ κρείττονος μέρους ψυχῆς μεταβέβληκεν εἰς θήρειον φύσιν, κἂν ἔτι", "st": "99"}, {"sp": "N", "t": "μένωσιν οἱ τοῦ σώματος χαρακτῆρες ἀνθρωπόμορφοι. τὴν μὲν οὖν ἀληθῆ μαγικήν, ὀπτικὴν ἐπιστήμην οὖσαν, ᾗ τὰ τῆς φύσεως ἔργα τρανοτέραις φαντασίαις αὐγάζεται, σεμνὴν καὶ περιμάχητον δοκοῦσαν εἶναι, οὐκ ἰδιῶται μόνον ἀλλὰ καὶ βασιλεῖς καὶ βασιλέων οἱ μέγιστοι καὶ μάλιστα οἱ Περσῶν διαπονοῦσιν οὕτως, ὥστ’ οὐδένα φασὶν ἐπὶ βασιλείαν δύνασθαι παραπεμφθῆναι παρ’ αὐτοῖς, εἰ μὴ πρότερον τοῦ μάγων γένους κεκοινωνηκὼς τυγχάνοι.", "st": "100"}, {"sp": "N", "t": "ἔστι δέ τι παράκομμα ταύτης, κυριώτατα φάναι κακοτεχνία, ἣν μηναγύρται καὶ βωμολόχοι μετίασι καὶ γυναίων καὶ ἀνδραπόδων τὰ φαυλότατα, περιμάττειν καὶ καθαίρειν κατεπαγγελλόμενα καὶ στέργοντας μὲν εἰς ἀνήκεστον ἔχθραν μισοῦντας δὲ εἰς ὑπερβάλλουσαν εὔνοιαν ἄξειν ὑπισχνούμενα φίλτροις καὶ ἐπῳδαῖς τισιν, εἶτα τοὺς ἀπλάστοις καὶ ἀκακωτάτοις ἤθεσι κεχρημένους ἀπατᾷ τε καὶ ἀγκιστρεύεται, μέχρις ἂν τὰς μεγίστας προσλάβωσι συμφοράς, δι’ ἃς οἰκείων καὶ συγγενῶν ὅμιλοι μεγάλοι καὶ πολυάνθρωποι κατὰ μικρὸν ὑπορρέοντες ἀψοφητὶ ταχέως ἐξεφθάρησαν.", "st": "101"}, {"sp": "N", "t": "εἰς ἅπερ, οἶμαι, πάντα ἀπιδὼν ὁ ἡμέτερος νομοθέτης οὐκ ἐᾷ τὰς κατὰ φαρμακευτῶν εἰς ὕστερον ἀναβάλλεσθαι δίκας, παραχρῆμα τὰς τιμωρίας ἀναπράττειν κελεύσας· αἱ γὰρ ὑπερθέσεις τοὺς μὲν ὑπαιτίους ἐνευκαιρεῖν τοῖς αὐτοῖς ἀδικήμασι παρορμῶσιν ἅτε θανατῶντας, τοὺς δὲ εἰς τὸ παθεῖν ὑπόπτους φοβερωτέρου δέους ἀναπιμπλᾶσι, τὴν ἐκείνων ζωὴν θάνατον αὑτῶν εἶναι νομίζοντας.", "st": "102"}, {"sp": "N", "t": "καθάπερ οὖν ἔχεις καὶ σκορπίους καὶ ὅσα ἰοβόλα, πρὶν δακεῖν ἢ τρῶσαι ἢ συνόλως ἐφορμῆσαι, θεασάμενοι μόνον χωρὶς ὑπερθέσεως κτείνομεν, προφυλαττόμενοι διὰ τὴν ἐνυπάρχουσαν αὐτοῖς κακίαν τὸ μηδὲν παθεῖν, τὸν αὐτὸν τρόπον καὶ ἀνθρώπους ἄξιον τιμωρεῖσθαι, οἳ φύσεως ἐπιλαχόντες ἡμέρου διὰ τὴν κοινωνίας αἰτίαν, λογικὴν ψυχήν, ἐπιτηδεύσει πρὸς θηρίων ἀτιθάσων ἀγριότητας μετέβαλον ἐν ἡδονῇ καὶ ὠφελείᾳ τῇ πάσῃ τιθέμενοι τὸ κακῶς ποιεῖν ὅσους ἂν δύνωνται.", "st": "103"}, {"sp": "N", "t": "Τοσαῦτ’ ἐν τῷ παρόντι περὶ φαρμακευτῶν ἀποχρώντως λελέχθω. προσήκει μέντοι μηδὲ τοῦτ’ ἀγνοεῖν, ὅτι καιροὶ συμπίπτουσιν ἀβούλητοι πολλάκις, ἐν οἷς ἀνδροφονεῖ τις οὐκ ἐπὶ τοῦτ’ ἐλθὼν ἢ παρεσκευασμένος, ἀλλ’ ἐξαπιναίως ἁρπασθεὶς ὑπ’ ὀργῆς, ἀνηκέστου καὶ ἐπιβούλου πάθους, ὃ καὶ τὸν ἔχοντα καὶ τὸν καθ’ οὗ γίνεται τὰ μέγιστα βλάπτει.", "st": "104"}, {"sp": "N", "t": "προελθὼν γὰρ ἔστιν ὅτε εἰς ἀγορὰν ἕνεκα πραγματείας ἐπειγούσης, ἐντυχών τινι προπετεστέρῳ κακηγορεῖν ἢ τύπτειν ἐπιχειροῦντι ἢ καὶ αὐτὸς ἄρξας τῆς πρὸς ἐκεῖνον διαφορᾶς, συμπλοκῆς γενομένης, ὑπὲρ τοῦ διαζευχθῆναι καὶ θᾶττον ἐκφυγεῖν ἢ πὺξ ἔπαισε τῇ χειρὶ ἢ λίθον ἀράμενος ἔρριψε·", "st": "105"}, {"sp": "N", "t": "καιρίως δὲ τῆς πληγῆς ἐνεχθείσης, εἰ μὲν εὐθὺς θνῄσκοι, καὶ ὁ παίσας θνῃσκέτω τὰ ἴσα οἷς διέθηκε παθών· ἐὰν δὲ παραχρῆμα μὲν ἐκ τῆς πληγῆς μὴ τελευτήσῃ, νόσῳ δὲ χρήσηται καὶ κλινήρης γενόμενος ἐπιμελείας τυχὼν τῆς προσηκούσης αὖθις ἐξαναστῇ καὶ προέλθῃ, κἂν μὴ ποσὶν ἀρτίοις πως δύνηται βαδίζειν ἀλλ’ ὑπερειδόντων τινῶν ἢ καὶ βακτηρίᾳ σκηριπτόμενος, διττὰς ὁ παίσας ἐκτινέτω ζημίας, τὴν μὲν εἰς ἀργίας ἐπανόρθωσιν, τὴν δ’ ἀντὶ τῶν ἰατρείων.", "st": "106"}, {"sp": "N", "t": "καταθεὶς δ’ ἀπηλλάχθω τῆς ἐπὶ τῷ θανάτῳ τιμωρίας, κἂν ὕστερον ὁ τὴν πληγὴν λαβὼν τελευτήσῃ· τάχα γὰρ οὐκ ἀπὸ τῆς πληγῆς, ἐπειδὴ ῥᾴων γενόμενος εἰς περίπατον προῆλθεν, ἀλλὰ καθ’ ἑτέρας αἰτίας, αἳ καὶ τοὺς ὑγιεινοτάτους τὰ σώματα πολλάκις ἐξαίφνης ἐπιθέμεναι διέφθειραν.", "st": "107"}, {"sp": "N", "t": "ἐὰν δὲ συμπλακεὶς γυναικί τις ἐγκύῳ πληγὴν ἐμφορήσῃ κατὰ τὴν γαστέρα, ἡ δὲ ἀμβλώσῃ, ἐὰν μὲν ἄπλαστον καὶ ἀδιατύπωτον τὸ ἀμβλωθὲν τύχῃ, ζημιούσθω, καὶ διὰ τὴν ὕβριν καὶ ὅτι ἐμποδὼν ἐγένετο τῇ φύσει ζῳογονῆσαι τὸ κάλλιστον τεχνιτευούσῃ καὶ δημιουργούσῃ ζῷον, ἄνθρωπον· εἰ δὲ ἤδη μεμορφωμένον, ἁπάντων μελῶν τὰς οἰκείους τάξεις καὶ ποιότητας ἀπειληφότων, θνῃσκέτω.", "st": "108"}, {"sp": "N", "t": "τὸ γὰρ τοιοῦτον ἄνθρωπός ἐστιν, ὃν ἐν τῷ τῆς φύσεως ἐργαστηρίῳ διεχρήσατο μήπω καιρὸν εἶναι νομιζούσης εἰς φῶς προαγαγεῖν, ἐοικὸς ἀνδριάντι ἐν πλαστικῇ κατακειμένῳ, πλέον οὐδὲν ἢ τὴν ἔξω παραπομπὴν καὶ ἄνεσιν ἐπιζητοῦντι.", "st": "109"}, {"sp": "N", "t": "Διὰ ταύτης τῆς προστάξεως καὶ ἕτερόν τι μεῖζον ἀπηγόρευται, βρεφῶν ἔκθεσις, ὃ παρὰ πολλοῖς τῶν ἄλλων ἐθνῶν ἕνεκα τῆς φυσικῆς ἀπανθρωπίας χειρόηθες ἀσέβημα γέγονεν.", "st": "110"}, {"sp": "N", "t": "εἰ γὰρ τοῦ μηδέπω ταῖς ὡρισμέναις τῶν καιρῶν περιόδοις ἀποκυηθέντος προνοητέον, ὡς μὴ ἐξ ἐπιβουλῆς τι δεινὸν πάθοι, πῶς οὐχὶ μᾶλλον τοῦ τελειογονηθέντος καὶ ὥσπερ εἰς ἀποικίαν ἣν ἔλαχον ἄνθρωποι προπεμφθέντος ἐπὶ τῷ μεταλαχεῖν τῶν τῆς φύσεως δωρεῶν, ἃς ἀνίησιν ἐκ γῆς καὶ ὕδατος καὶ ἀέρος καὶ οὐρανοῦ, παρέχουσα τῶν μὲν οὐρανίων τὴν θέαν, τῶν δὲ ἐπιγείων τὸ κράτος καὶ τὴν ἡγεμονίαν, καὶ πάσαις μὲν χορηγοῦσα ταῖς αἰσθήσεσιν ἄφθονα τὰ πάντων, τῷ δὲ νῷ καθάπερ μεγάλῳ βασιλεῖ τὰ μὲν διὰ τούτων ὡς ἂν δορυφόρων ὅσα αἰσθητά, τὰ δ’ ἄνευ τούτων ὅσα λόγῳ καταληπτά;", "st": "111"}, {"sp": "N", "t": "τοσούτων οὖν ἀποστεροῦντες ἀγαθῶν τοὺς παῖδας οἱ τροφεῖς, ἅμα τῇ γενέσει τούτων μηδενὸς μεταδιδόντες, ἴστωσαν νόμους φύσεως καταλύοντες καὶ τὰ μέγιστα κατηγοροῦντες αὑτῶν, φιληδονίαν, μισανθρωπίαν, ἀνδροφονίαν καὶ — τὸ χαλεπώτατον ἄγος — τεκνοκτονίαν.", "st": "112"}, {"sp": "N", "t": "φιλήδονοι μὲν γάρ, εἰ μὴ σπορᾶς ἕνεκα τέκνων καὶ τοῦ διαιωνίσαι τὸ γένος συνέρχονται γυναιξὶν ἀλλὰ θηρώμενοι συῶν ἢ τράγων τρόπον τὴν ἐξ ὁμιλίας ἀπόλαυσιν· μισάνθρωποι δὲ τίνες ἂν εἶεν μᾶλλον ἢ οἱ τῶν γεννηθέντων ἐχθροὶ καὶ ἀμείλικτοι δυσμενεῖς; εἰ μή τις οὕτως ἐστὶν ἠλίθιος, ὡς ὑπολαβεῖν ὅτι πρὸς τοὺς ἀλλοτρίους ἔνσπονδοι γένοιντ’ ἂν οἱ τοὺς ἡνωμένους κατὰ γένος ἔκσπονδα εἰργασμένοι.", "st": "113"}, {"sp": "N", "t": "τάς γε μὴν ἀνδροφονίας καὶ τεκνοκτονίας ἐναργεστάταις βεβαιοῦνται πίστεσιν οἱ μὲν αὐτόχειρες γινόμενοι καὶ τὴν πρώτην εἰσπνοὴν τῶν βρεφῶν πιέζοντες καὶ ἀναθλίβοντες ὑπὸ ὠμότητος καὶ δεινῆς ἀναλγησίας, οἱ δὲ εἰς ποταμὸν ἢ θαλάττης βυθὸν ἀφιέντες, ὅταν ἀπαιωρήσωσιν ἄχθος, ἵνα θᾶττον τῷ βάρει καταφέρηται·", "st": "114"}, {"sp": "N", "t": "οἱ δ’ ἐπ’ ἐρημίαν κομίζουσιν ἐκθήσοντες, ὡς μὲν αὐτοί φασιν, ἐλπίδι σωτηρίας, ὡς δὲ τἀληθὲς ἔχει, πρὸς ἀνιαροτάτας συμφοράς· ὅσα γὰρ ἀνθρωπίνων σαρκῶν ἅπτεται θηρία, μηδενὸς ἀνείργοντος, ἐπιφοιτᾷ καὶ εὐωχεῖται τῶν βρεφῶν, καλῆς θοίνης, ἣν οἱ μόνοι κηδεμόνες καὶ πρὸ τῶν ἄλλων σῴζειν ὀφείλοντες, πατὴρ καὶ μήτηρ, προὔθεσαν· καὶ τὰ λείψανα μέντοι προσεπιλιχμῶνται τῶν οἰωνῶν οἱ σαρκοβόροι καταπτάντες, ὅταν μὴ προαίσθωνται· αἰσθόμενοι γὰρ καὶ περὶ τῶν ὅλων πρὸς τοὺς χερσαίους θῆρας κονίονται.", "st": "115"}, {"sp": "N", "t": "φέρε δ’ οὖν τῶν ὁδῷ παριόντων τινὰς ἡμέρῳ κινηθέντας πάθει λαβεῖν οἶκτον καὶ ἔλεον τῶν ἐκτεθέντων, ὡς ἀνελέσθαι τε καὶ τροφῆς μεταδοῦναι καὶ τῆς ἄλλης ἐπιμελείας ἀξιῶσαι· ταυτὶ τὰ οὕτως χρηστὰ ἔργα τί νομίζομεν; ἆρ’ οὐ τῶν γεννησάντων εἶναι καταδίκην, εἴ γ’ οἱ μὲν ἀλλότριοι τὰ γονέων, οἱ δὲ γονεῖς οὐδὲ τὰ τῶν ἀλλοτρίων εἰς εὔνοιαν ἐπετήδευσαν; πόρρωθεν οὖν τὴν βρεφῶν ἔκθεσιν ἀπεῖπε δι’ ὑπονοιῶν θάνατον,", "st": "116"}, {"sp": "N", "t": "ὡς ἔφην, ὁρίσας κατὰ τῶν αἰτίων ἀμβλώσεως τὰ μεμορφωμένα ἤδη κυϊσκούσαις· καίτοι τὰ μὲν ἔτι κατὰ γαστρὸς προσεχόμενα τῇ μήτρᾳ τῶν κυουσῶν εἶναι μέρη λέγεται παρά τε φυσικοῖς ἀνδράσιν, οἷς ὁ θεωρητικὸς διαπονεῖται βίος, καὶ παρὰ ἰατρῶν τοῖς δοκιμωτάτοις, οἳ τὴν ἀνθρώπου κατασκευὴν διηρεύνησαν τά τ’ ἐν ὄψει καὶ τὰ ἀφανῆ μετ’ ἐπιμελείας ἐξ ἀνατομῆς ἀκριβώσαντες, ἵν’, εἰ χρεία τις γένοιτο θεραπείας, μηδὲν ἀγνοίᾳ παρολιγωρηθὲν αἴτιον μεγάλου κινδύνου γένηται.", "st": "117"}, {"sp": "N", "t": "τὰ δ’ ἀποκυηθέντα τῆς τε συμφυΐας ἀπέζευκται καὶ διυφειμένα καθ’ αὑτὰ ζῷα γέγονεν οὐδενὸς ἐπιδεᾶ τῶν ὅσα συμπληρωτικὰ τῆς ἀνθρωπίνης φύσεώς ἐστιν, ὥστε ἀνενδοιάστως ἀνδροφόνον εἶναι τὸν βρέφος ἀναιροῦντα, τοῦ νόμου μὴ ἐπὶ ταῖς ἡλικίαις ἀλλ’ ἐπὶ τῷ γένει παρασπονδουμένῳ δυσχεραίνοντος.", "st": "118"}, {"sp": "N", "t": "εἰ μέντοι καὶ ἡλικιῶν ἔδει προμηθεῖσθαι, δοκεῖ μοί τις ἂν δεόντως ἀγανακτῆσαι μᾶλλον ἐπὶ τοῖς ἀναιροῦσι βρέφη· πρὸς μὲν γὰρ τοὺς τελείους μυρίαι προφάσεις εὔλογοι προσκρουσμάτων τε καὶ διαφορῶν, τοῖς δὲ κομιδῇ νηπίοις ἄρτι παρεληλυθόσιν εἰς φῶς καὶ τὸν ἀνθρώπινον βίον οὐδ’ ἐπιψεύσασθαι κατηγορίαν ἀκακωτάτοις οὖσιν ἐνδέχεται. διὸ πάντων ὠμότατοι καὶ ἀνηλεέστατοι κριθεῖεν ἂν οἱ ἐπαποδυόμενοι ταῖς τούτων ἐπιβουλαῖς, οὓς ἐχθαίρων ὁ ἱερὸς νόμος ἐνόχους ἀπεφήνατο.", "st": "119"}, {"sp": "N", "t": "Τὸν μὴ ἑκουσίῳ γνώμῃ τοῦ κτείναντος ἀναιρεθέντα φησὶν ὁ ἱερὸς νόμος παραδεδόσθαι ὑπὸ θεοῦ χερσὶν ἀνδροφόνοις, τῇ μὲν ἀπολογούμενος ὑπὲρ τοῦ δόξαντος ἀνελεῖν ὡς ἔνοχον ἀνελόντος —", "st": "120"}, {"sp": "N", "t": "μὴ γὰρ ἄν ποτε τὸν ἵλεω καὶ συγγνώμονα θεὸν ἐπ’ ἀναιρέσει τόν γε ἀναίτιον ἐκδοῦναι, ἀλλ’ ὅστις τὰς μὲν παρὰ ἀνθρώποις κρίσεις εὐμηχάνως ἕνεκα τοῦ πολυτρόπου διαδιδράσκει, πρὸς δὲ τὸ τῆς φύσεως ἀχθεὶς ἀφανὲς δικαστήριον ἑάλω, ἐν ᾧ μόνῳ τἀληθὲς ἀκραιφνέστατον ὁρᾶται, λόγων τέχναις οὐκ ἐπισκιαζόμενον, οὐδὲ γὰρ λόγους τὴν ἀρχὴν παραδέχεται βουλήματα ἀπαμπίσχον καὶ διανοίας ἀφανεῖς εἰς τοὐμφανὲς ἄγον —, τῇ δὲ καὶ τὸν ἀνελόντα φόνῳ μὲν οὐ ποιῶν ὑπόδικον ἅτε θείᾳ κρίσει δόξαντα ὑπηρετῆσαι, μιάσματι δὲ ἀδηλουμένῳ καὶ βραχεῖ πάντως, ὃ παραιτητὸν καὶ συγγνωστόν ἐστι.", "st": "121"}, {"sp": "N", "t": "χρῆται γὰρ ὁ θεὸς τοῖς ὀλίγα καὶ ἰάσιμα διαμαρτάνουσι κατὰ τῶν μέγιστα καὶ ἀνίατα ἠδικηκότων ὑπηρέταις κολάσεως, οὐκ ἐκείνους ἀποδεχόμενος, ἀλλ’ ὡς ἂν ὄργανα παραλαμβάνων ἐπιτήδεια πρὸς τιμωρίαν, ἵνα μηδεὶς ὅλῳ βίῳ καθαρὸς ὢν καὶ ἐκ καθαρῶν φόνου, κἂν δικαιότατος ᾖ, προσάψηται.", "st": "122"}, {"sp": "N", "t": "φυγὴν οὖν κατὰ τοῦ κτείναντος ἀκουσίως ὥρισεν, οὐχ ὅπῃ τύχοι οὐδ’ εἰς ἀεί· πόλεις μὲν γὰρ ἓξ ἀπένειμεν, ὀγδόην μοῖραν ὧν ἔλαχεν ἡ ἱερωμένη φυλή, τοῖς ἁλοῦσιν, ἃς ἀπὸ τοῦ συμβεβηκότος ὠνόμασε “φυγαδευτηρίων”· χρόνον δὲ τῆς φυγῆς τὸν βίον τοῦ ἀρχιερέως προσενομοθέτησε κάθοδον μετὰ τὴν ἐκείνου τελευτὴν ἐπιτρέπων.", "st": "123"}, {"sp": "N", "t": "αἰτία δὲ τούτου μὲν προτέρα ἥδε· ἡ λεχθεῖσα φυλὴ τὰς πόλεις εἴληφεν ἆθλον ἀνδροφονίας εὐαγοῦς, ἣν ἀριστειῶν ὅσαι πώποτε γεγόνασιν ἐπιφανεστάτην καὶ μεγίστην ὑποληπτέον.", "st": "124"}, {"sp": "N", "t": "ἡνίκα γὰρ ὁ προφήτης εἰς τὸ περιμηκέστατον καὶ ἱερώτατον τῶν κατ’ ἐκεῖνον τὸν τόπον ὀρῶν ἀνακληθεὶς ἐθεσπίζετο τὰ γένη τῶν ἐν εἴδει νόμων καὶ πλείους ἦν ἀφανὴς ἡμέρας, οἱ μὴ τὰς φύσεις εἰρηνικοὶ τῶν ἐξ ἀναρχίας κακιῶν πάντα κατέπλησαν καὶ τέλος προσέθηκαν ἀσέβειαν· τὰς μὲν ἀρίστας καὶ καλὰς ὑφηγήσεις περὶ τῆς τοῦ ὄντως ὄντος θεοῦ τιμῆς χλευάσαντες, ταῦρον δὲ κατασκευασάμενοι χρυσοῦν, Αἰγυπτιακοῦ μίμημα τύφου, θυσίας ἀνῆγον ἀθύτους καὶ ἑορτὰς ἀνεόρτους καὶ χοροὺς ἀχορεύτους ἐπετέλουν σὺν ᾠδαῖς καὶ ὕμνοις ἀντὶ θρήνων.", "st": "125"}, {"sp": "N", "t": "ἡ δὲ λεχθεῖσα φυλὴ πάνυ χαλεπῶς ἐνεγκοῦσα τὴν αἰφνίδιον ἐκδιαίτησιν καὶ ζήλῳ πυρωθεῖσα διὰ μισοπόνηρον πάθος, ὑπόπλεῳ πάντες ὀργῆς, μεμηνότες, ἐνθουσιῶντες, ὡς ἀφ’ ἑνὸς συνθήματος ὁπλισάμενοι, διττὴν μεθύοντας μέθην, τὴν μὲν ἀσεβείᾳ, τὴν δὲ οἴνῳ, μάλα καταφρονητικῶς ἐπιστροφάδην ἀνῄρουν, ἀπὸ τῶν οἰκειοτάτων καὶ φιλτάτων ἀρξάμενοι, φίλον καὶ συγγένειαν ἓν τὸ θεοφιλὲς εἶναι νομίζοντες· καὶ βραχεῖ μέρει ἡμέρας τέσσαρες πρὸς ταῖς εἴκοσι χιλιάδες ἀνῃρέθησαν, ὧν αἱ συμφοραὶ τοὺς συναπονοεῖσθαι μέλλοντας ἐνουθέτησαν, δέει τοῦ μὴ τὰ παραπλήσια παθεῖν.", "st": "126"}, {"sp": "N", "t": "ταύτην τὴν στρατείαν ἐθελουργὸν καὶ αὐτοκέλευστον ὑπὲρ εὐσεβείας καὶ ὁσιότητος τῆς εἰς τὸν ὄντως ὄντα θεὸν γενομένην οὐκ ἄνευ μεγάλων κινδύνων τοῖς ἀραμένοις τοὺς ἀγῶνας αὐτὸς ὁ πατὴρ τῶν ὅλων ἀπεδέξατο καὶ τοὺς ἀνελόντας δικάσας παρ’ αὑτῷ καθαροὺς εἶναι παντὸς ἄγους καὶ μιάσματος ἱερωσύνην τῆς ἀνδραγαθίας", "st": "127"}, {"sp": "N", "t": "τούτοις ἀντιδωρεῖται. τὸν οὖν ἀκούσιον δράσαντα φόνον κελεύει φυγεῖν εἰς ἐνίας ὧν ἔλαχον οὗτοι πόλεις ἕνεκα παρηγορίας καὶ ὑπὲρ τοῦ μὴ ἀπογινώσκειν τὴν εἰς ἅπαν ἀσφάλειαν, ὑπομιμνῃσκόμενον ἐκ τοῦ τόπου τὸ ἄφοβον καὶ λογιζόμενον, ὅτι τοῖς ἑκουσίως ἀπεκτονόσιν οὐ μόνον ἀμνηστία δέδοται ἀλλὰ καὶ γέρα μεγάλα καὶ περιμάχητα καὶ πολλῆς εὐδαιμονίας, εἰ δὲ τούτοις, πολὺ μᾶλλον τοῖς μὴ ἐκ προνοίας ἀνελοῦσιν, εἰ καὶ μηδὲν τῶν ἐπὶ τιμῇ, ἀλλ’ αὐτὸ γοῦν τὸ πανύστατον, μὴ ἀνταναιρεθῆναι· δι’ οὗ παρίσταται τὸ μὴ πᾶσαν ἀνδροφονίαν ἐπίληπτον ἀλλὰ τὴν σὺν ἀδικίᾳ μόνην εἶναι, καὶ τῶν ἄλλων ἐπαινετὴν μὲν τὴν κατὰ πόθον καὶ ζῆλον ἀρετῆς, οὐ ψεκτὴν δὲ τὴν ἀκούσιον.", "st": "128"}, {"sp": "N", "t": "ἥδε μὲν αἰτία προτέρα λελέχθω, δευτέραν δ’ αὐτίκα μηνυτέον· βούλεται ὁ νόμος τὸν ἀκουσίως ἀποκτείναντα διασῴζειν, εἰδὼς γνώμῃ μὲν οὐκ ἔνοχον χερσὶ δὲ ὑπηρετήσαντα τῇ τῶν ἀνθρωπίνων ἐφόρῳ δίκῃ πραγμάτων· ἐφεδρεύουσι γὰρ ἐχθροὶ φονῶντες οἱ τοῦ τεθνεῶτος ἀγχιστεῖς, οἳ δι’ ὑπερβάλλοντα οἶκτον καὶ πένθος ἀπαρηγόρητον ἵενται πρὸς ἄμυναν ἀλόγῳ φορᾷ τἀληθὲς καὶ τὸ φύσει δίκαιον οὐκ ἐξετάζοντες.", "st": "129"}, {"sp": "N", "t": "ἐπέτρεψεν οὖν τῷ τοιούτῳ καταφεύγειν οὔτε εἰς ἱερὸν ἅτε μήπω κεκαθαρμένῳ οὔτε εἰς ἠμελημένον καὶ ἀφανὲς χωρίον, ἵνα μὴ ῥᾳδίως ἐκδοθῇ καταφρονηθείς, ἀλλ’ εἰς ἱερόπολιν, ἥτις ἐστὶν ἱεροῦ καὶ βεβήλου τόπου μεθόριος, τρόπον τινὰ δεύτερον ἱερόν· αἱ γὰρ τῶν ἱερωμένων πόλεις σεμνότεραι τῶν ἄλλων εἰσίν, ἐφ’ ὅσον, οἶμαι, καὶ οἰκήτορες οἰκητόρων ἐντιμότεροι· βούλεται γὰρ τῇ τῆς ὑποδεξαμένης προνομίᾳ βεβαιοτάτην ἀσφάλειαν περιποιῆσαι τῷ καταφυγόντι.", "st": "130"}, {"sp": "N", "t": "χρόνον δ’, ὡς ἔφην, ὥρισε τῆς καθόδου τὴν τοῦ μεγάλου ἱερέως τελευτὴν αἰτίας ἕνεκα τοιᾶσδε· ὥσπερ ἑνὸς ἑκάστου τῶν δολοφονηθέντων οἱ συγγενεῖς εἰσιν ἔφεδροι τῆς κατὰ τῶν δολοφονησάντων δίκης καὶ τιμωρίας, οὕτως καὶ τοῦ σύμπαντος ἔθνους συγγενὴς καὶ ἀγχιστεὺς κοινὸς ὁ ἀρχιερεύς ἐστι, πρυτανεύων μὲν τὰ δίκαια τοῖς ἀμφισβητοῦσι κατὰ τοὺς νόμους, εὐχὰς δὲ καὶ θυσίας τελῶν καθ’ ἑκάστην ἡμέραν καὶ τὰ ἀγαθὰ αἰτούμενος ὡς ὑπὲρ ἀδελφῶν καὶ γονέων καὶ τέκνων, ἵνα πᾶσα ἡλικία καὶ πάντα μέρη τοῦ ἔθνους ὡς ἑνὸς σώματος εἰς μίαν καὶ τὴν αὐτὴν ἁρμόζηται κοινωνίαν εἰρήνης καὶ εὐνομίας ἐφιέμενα.", "st": "131"}, {"sp": "N", "t": "τοῦτον οὖν εὐλαβείσθω πᾶς ὁ ἀκουσίως ἀνελὼν ὡς ὑπέρμαχον καὶ προαγωνιστὴν τῶν ἀναιρεθέντων καὶ εἴσω τῆς πόλεως εἰς ἣν κατέφυγε κατακεκλείσθω, μὴ ἐπιθαρρῶν ἔξω προέρχεσθαι τειχῶν, εἰ δή τινα ποιεῖται λόγον ἀσφαλείας καὶ τοῦ ζῆν ἀκινδύνως.", "st": "132"}, {"sp": "N", "t": "ὅταν οὖν λέγῃ “μὴ ἐπανίτω ὁ φυγάς, ἕως ἂν ἀποθάνῃ ὁ ἱερεὺς ὁ μέγας”, ἴσον τι τούτῳ φησίν· ἕως ἂν ἀποθάνῃ ὁ πάντων κοινὸς ἀγχιστεύς, ᾧ μόνῳ καὶ τὰ τῶν ζώντων καὶ τὰ τῶν τετελευτηκότων ἐφεῖται βραβεύειν.", "st": "133"}, {"sp": "N", "t": "τὴν μὲν οὖν καὶ νεωτέρων ἀκοαῖς ἐφαρμόζουσαν αἰτίαν τοιαύτην εἶναι συμβέβηκεν. ἣν δὲ πρεσβυτέροις καὶ τελείοις τὸ ἦθος θέμις ἀναφέρειν, ἥδ’ ἐστί· τῶν μὲν ἑκουσίων ἀδικημάτων αὐτὸ μόνον ἰδιώτας καθαρεύειν ἐφείσθω, λεγέτω δ’ εἰ βούλεταί τις καὶ τοὺς ἄλλους ἱερεῖς, ἀμφοτέρων δ’ ἑκουσίων τε καὶ ἀκουσίων κατὰ τὸν ἐξαίρετον λόγον τὸν ἀρχιερέα.", "st": "134"}, {"sp": "N", "t": "προσάπτεσθαι γὰρ αὐτῷ μιάσματος τὸ σύνολον οὐ θεμιτόν, οὔτ’ ἐκ προνοίας οὔτε κατὰ τροπὴν τῆς ψυχῆς ἀβούλητον, ἵνα ἱεροφάντης ὢν κοσμῆται καθ’ ἑκάτερον, διανοίᾳ τε χρώμενος ἀνεπιλήπτῳ καὶ εὐπραγίᾳ βίου, ᾧ μηδὲν ὄνειδος πρόσεστι.", "st": "135"}, {"sp": "N", "t": "τῷ δὴ τοιούτῳ γένοιτ’ ἂν ἀκόλουθον ὑποβλέπεσθαι καὶ τοὺς ἀκουσίως ἀπεκτονότας [οὐχ] ὡς ἐναγεῖς, ἀλλ’ οὐχ ὡς καθαροὺς καὶ παντὸς ἀμετόχους ἁμαρτήματος, καὶ εἰ τὰ μάλιστα τοῖς τῆς φύσεως ὑπηρετῆσαι βουλήμασιν ἔδοξαν τισαμένης διὰ τούτων τοὺς ἀναιρεθέντας, ὧν ἀφανῶς αὕτη δικάσασα παρ’ ἑαυτῇ θάνατον κατέγνω. ταῦτα μὲν ἐπ’ ἐλευθέροις καὶ ἀστοῖς· ἑξῆς δὲ καὶ περὶ οἰκετῶν νομοθετεῖται βιαίως ἀναιρεθέντων.", "st": "136"}, {"sp": "N", "t": "Θεράποντες τύχῃ μὲν ἐλάττονι κέχρηνται, φύσεως δὲ τῆς αὐτῆς μεταποιοῦνται τοῖς δεσπόταις. τῷ δὲ θείῳ νόμῳ κανὼν τῶν δικαίων ἐστὶν οὐ τὸ τῆς τύχης ἀλλὰ τὸ τῆς φύσεως ἐναρμόνιον. διὸ προσήκει τοὺς κυρίους μὴ κατακόρως χρῆσθαι ταῖς ἐξουσίαις κατὰ τῶν οἰκετῶν, ἀλαζονείαν καὶ ὑπεροψίαν καὶ δεινὴν ὠμότητα ἐπιδεικνυμένους· ταῦτα γὰρ οὐκ ἔστι δείγματα ψυχῆς εἰρηνικῆς ἀλλ’ ὑπὸ ἀκρασίας τὸ ἀνυπεύθυνον ζηλούσης κατὰ τυραννικὴν δυναστείαν.", "st": "137"}, {"sp": "N", "t": "ὁ γὰρ τὴν μὲν ἰδίαν οἰκίαν ὥσπερ ἄκραν ἐπιτειχίσας, παρρησίας δὲ τῶν ἔνδον μηδενὶ μεταδιδούς, ἀλλὰ πρὸς ἅπαντας ἠγριωμένος ὑπὸ τῆς ἐμφύτου τάχα δὲ καὶ ἐπιτετηδευμένης μισανθρωπίας, τύραννός ἐστιν ἐλάττοσι παρασκευαῖς χρώμενος.", "st": "138"}, {"sp": "N", "t": "ἐξ ὧν διελέγχεται μὴ στησόμενος ἐπὶ τῶν αὐτῶν, εἰ μειζόνων λάβοιτο χρημάτων· διαβήσεται γὰρ εὐθὺς ἐπὶ πόλεις τε καὶ χώρας καὶ ἔθνη τὴν αὑτοῦ πατρίδα προδουλωσάμενος εἰς ἔνδειξιν τοῦ μηδενὶ μέλλειν τῶν ἄλλων ὑπηκόων ἡμέρως προσφέρεσθαι.", "st": "139"}, {"sp": "N", "t": "σαφῶς οὖν ὁ τοιοῦτος ἴστω μὴ τὴν τοῦ συνεχῶς καὶ εἰς πολλοὺς ἁμαρτάνειν ἄδειαν ἕξων· ἐναντιώσεται γὰρ ἡ μισοπόνηρος αὐτῷ δίκη, ἡ βοηθὸς καὶ ὑπέρμαχος τῶν ἀδικηθέντων, ἣ λόγον καὶ εὐθύνας αὐτὸν τῆς περὶ τοὺς πεπονθότας συμφορᾶς ἀπαιτήσει·", "st": "140"}, {"sp": "N", "t": "κἂν ἄρα φάσκῃ πληγὰς ἕνεκα νουθεσίας ἐντεῖναι μὴ διανοηθεὶς ἀνελεῖν, οὐκ εὐθὺς βαδιεῖται γεγηθώς, ἀλλ’ εἰς δικαστήριον ἀπαχθεὶς παρ’ ἀκριβέσι λογισταῖς τῆς ἀληθείας ἐξετασθήσεται, πότερον ἑκὼν ἀπέκτεινεν ἢ ἄκων· κἂν ἐπιβεβουλευκὼς ἀνευρίσκηται γνώμῃ ἀνοσίῳ, θνῃσκέτω, μηδὲν παρόσον δεσπότης ἐστὶ κερδαίνων εἰς τὸ σωθῆναι.", "st": "141"}, {"sp": "N", "t": "ἐὰν δὲ μὴ εὐθὺς ἐκ τῶν πληγῶν οἱ τυπτηθέντες ἀναιρεθῶσιν, ἀλλὰ βιώσωσιν ἡμέραν μίαν ἢ καὶ δύο, μηκέθ’ ὁμοίως ὁ δεσπότης ὑπόδικος ἔστω φόνου, πλεονέκτημα εἰς ἀπολογίαν πεπορισμένος τὸ μήτε παραχρῆμα τύπτων ἀνελεῖν μήθ’ ὕστερον, ἔχων κατὰ τὴν οἰκίαν, ἀλλὰ ζῆν ἐάσας ὅσον βιοῦν οἷοί τε ἦσαν χρόνον, εἰ καὶ παντάπασιν ὀλίγον· χωρὶς τοῦ μηδένα οὕτως ἠλίθιον εἶναι, ὡς λυπεῖν ἕτερον ἐπιχειρεῖν, ἐν οἷς αὐτὸς ἀδικηθήσεται.", "st": "142"}, {"sp": "N", "t": "κτείνων δέ τις οἰκέτην πολὺ πρότερον ἑαυτὸν βλάπτει, ὑπηρεσιῶν τε ἃς παρὰ ζῶντος εἶχε στερόμενος καὶ τὴν τιμὴν ζημιούμενος καὶ πλείστην ἴσως. ἐὰν μέντοι θανάτου πεπραχὼς ἄξια τυγχάνῃ, πρὸς τοὺς δικαστὰς ἀγέτω καὶ δηλούτω τὸ ἀδίκημα, τοὺς νόμους κυρίους ποιῶν τῆς τιμωρίας ἀλλὰ μὴ ἑαυτόν.", "st": "143"}, {"sp": "N", "t": "Ἐάν τινα ταῦρος ἀναπείρας ἀποκτείνῃ, καταλευέσθω—ἀσφαγὴς γὰρ ἱερείοις—καὶ ἄβρωτα ἔστω τὰ τούτου κρέα. διὰ τί; ὅτι τροφὴν ἢ προσόψημα τροφῆς ἀνθρώπων γίνεσθαι τὰ τοῦ κτείναντος ἄνθρωπον οὐχ ὅσιον.", "st": "144"}, {"sp": "N", "t": "ἐὰν δὲ ὁ τοῦ κτήνους κύριος ἄγριον εἰδὼς καὶ ἀτίθασον μήτε καταδήσῃ μήτε κατακλείσας φυλάττῃ, τύχῃ δὲ καὶ παρ’ ἑτέρων πεπυσμένος ὅτι οὐκ ἔστι χειρόηθες, ἄφετον ἐάσας ἐκνέμεσθαι ὥσπερ αἴτιος ὑπόδικος ἔστω· καὶ τὸ μὲν ἀναπεῖραν αὐτίκα θνῃσκέτω, ὁ δὲ κύριος προσαναιρείσθω ἢ λύτρα καὶ σῶστρα κατατιθέσθω, τὸ δὲ δικαστήριον ὅ τι χρὴ παθεῖν ἢ ἀποτῖσαι διαγνώσεται. εἰ μέντοι δοῦλος ὁ ἀναιρεθεὶς εἴη, τὴν τιμὴν ἐπανορθούσθω τῷ δεσπότῃ.", "st": "145"}, {"sp": "N", "t": "ἐὰν δὲ μὴ ἄνθρωπον ἀλλὰ κτῆνος ἀναπείρῃ, τὸ τεθνηκὸς ὁ τοῦ κτείναντος λαβὼν δεσπότης τὸ ὅμοιον ἀποτισάτω, [διότι τὸ ἀνήμερον τοῦ ἰδίου προαισθανόμενος οὐκ ἐφυλάξατο· κἂν αὐτὸ μέντοι τὸ θρέμμα ἀλλότριον ἀνέλῃ, πάλιν ὅμοιον ἀποτινέτω,] χάριν εἰδὼς ἐπὶ τῷ μὴ πλείονα ζημίαν ὑπομένειν ἄρξας ἐπηρείας.", "st": "146"}, {"sp": "N", "t": "Ὀρύγματα γῆς εἰώθασί τινες εὖ μάλα βαθύνειν ἢ φλέβας πηγαζούσας ἀναστέλλοντες ἢ πρὸς ὑποδοχὴν ὀμβρίου ὕδατος, εἶθ’ ὑπονόμους εὐρύναντες ἀφανεῖς, δέον τὰ στόμια ἢ περιοικοδομῆσαι ἢ περιπωμάσαι, κατά τινα δεινὴν ῥᾳθυμίαν ἢ φρενοβλάβειαν ἐπ’ ὀλέθρῳ τινῶν εἴασαν ἀχανῆ.", "st": "147"}, {"sp": "N", "t": "ἐὰν οὖν τις τῶν ὁδῷ παριόντων μὴ προαισθόμενος κατὰ κενοῦ ἐπιβὰς ἐνεχθῇ καὶ τελευτήσῃ, ἐπιγραφέσθωσαν οἱ βουλόμενοι ὑπὲρ τοῦ τετελευτηκότος πρὸς τοὺς τὸ ὄρυγμα ποιησαμένους καὶ τιμάτω τὸ δικαστήριον ὅ τι χρὴ παθεῖν ἢ ἀποτῖσαι. ἐὰν δὲ θρέμμα κατενεχθὲν ἀποθάνῃ, τὴν ἀξίαν τιμὴν ὡς ζῶντος ἐπανορθούσθωσαν τῷ δεσπότῃ τὸ νεκρὸν αὐτοὶ λαβόντες.", "st": "148"}, {"sp": "N", "t": "ἀδελφὸν δὲ καὶ συγγενὲς ἀδίκημα δρῶσι τῷ λεχθέντι καὶ ὅσοι κατασκευάζοντες οἰκίας ἰσόπεδα καταλείπουσι τὰ τέγη, περιστεφανοῦν θωρακίοις δέον ὑπὲρ τοῦ μή τινα κατακρημνισθῆναι λαθόντα· φόνον γάρ, εἰ δεῖ τἀληθὲς εἰπεῖν, δρῶσι, κἂν μηδεὶς ὑποσυρεὶς ἀποθάνῃ, τό γε ἐπ’ αὐτοὺς ἧκον μέρος. κολαζέσθωσαν οὖν ἐν ἴσῳ τοῖς ἀχανῆ τὰ στόμια τῶν ὀρυγμάτων καταλείπουσι.", "st": "149"}, {"sp": "N", "t": "Λύτρα παρὰ ἀνδροφόνου, ὃν δέον τεθνάναι, διαγορεύει ὁ νόμος μὴ ἐξεῖναι λαμβάνειν ἐπὶ μειώσει τῆς τιμωρίας ἢ ὑπαλλαγῇ φυγῆς ἀντὶ θανάτου· αἵματι γὰρ αἷμα καθαίρεται, τῷ τοῦ κτείναντος τὸ τοῦ ἐπιβουλευθέντος.", "st": "150"}, {"sp": "N", "t": "ἐπεὶ δ’ ὅρον οὐκ ἔχουσιν οἱ πονηροὶ τὰς φύσεις τοῦ πλημμελεῖν, ἀλλ’ ἀεὶ μεγαλουργοῦσι προσυπερβάλλοντες καὶ τὰς κακίας ἐπιτείνουσι καὶ διαίρουσι πρὸς τὸ ἄμετρον καὶ ἀπερίγραφον, μυρίους μὲν θανάτους, εἴπερ οἷόν τε ἦν, ὥρισεν ἂν κατ’ αὐτῶν ὁ νομοθέτης· ἐπεὶ δὲ τοῦτ’ οὐκ ἐνεδέχετο, τιμωρίαν ἄλλην προσδιατάττεται κελεύων τοὺς ἀνελόντας ἀνασκολοπίζεσθαι.", "st": "151"}, {"sp": "N", "t": "καὶ τοῦτο προστάξας ἀνατρέχει πάλιν ἐπὶ τὴν αὑτοῦ φιλανθρωπίαν, ἡμερούμενος πρὸς τοὺς ἀνήμερα εἰργασμένους, καί φησι· μὴ ἐπιδυέτω ὁ ἥλιος ἀνεσκολοπισμένοις, ἀλλ’ ἐπικρυπτέσθωσαν γῇ πρὸ δύσεως καθαιρεθέντες. ἦν γὰρ ἀναγκαῖον τοὺς ἅπασι τοῖς μέρεσι τοῦ κόσμου πολεμίους μετεωρίσαντας εἰς τοὐμφανὲς ἐπιδείξασθαι μὲν αὐτοὺς ἡλίῳ καὶ οὐρανῷ καὶ ἀέρι καὶ ὕδατι καὶ γῇ κολασθέντας, πάλιν δὲ εἰς τὸν νεκρῶν χῶρον ὑποσῦραί τε καὶ καταχῶσαι, ὅπως μὴ τὰ ὑπὲρ γῆν μιαίνωσι.", "st": "152"}, {"sp": "N", "t": "Παγκάλως μέντοι κἀκεῖνο διατέτακται, πατέρας ὑπὲρ υἱῶν μὴ ἀποθνῄσκειν μηδ’ υἱοὺς ὑπὲρ γονέων, ἀλλ’ ἕκαστον τῶν ἄξια θανάτου δεδρακότων αὐτὸν ἰδίᾳ μόνον ἀναιρεῖσθαι, διὰ τοὺς ἢ βίαν τοῦ δικαίου προτιμῶντας ἢ πάνυ φιλοστόργους.", "st": "153"}, {"sp": "N", "t": "οὗτοι μὲν γὰρ διὰ περιττὴν καὶ ὑπερβάλλουσαν εὔνοιαν ἐθελήσουσι πολλάκις ἄσμενοι προαποθνῄσκειν, αὑτοὺς ἐπιδιδόντες ὑπὲρ τῶν ἐνόχων οἱ ἀνυπαίτιοι, μέγα κέρδος νομίζοντες τὸ μὴ ἐπιδεῖν κολαζομένους ἢ τοὺς γεννήσαντας υἱοὶ ἢ τοὺς παῖδας γονεῖς, ὡς ἀβίωτον καὶ παντὸς ἀργαλεώτερον θανάτου τὸν αὖθις χρόνον βιωσόμενοι.", "st": "154"}, {"sp": "N", "t": "πρὸς οὓς λεκτέον· “ἡ εὔνοια ὑμῶν οὐκ ἔχει καιρόν, τὰ δ’ ὅσα μὴ ἐν καιρῷ ψέγεται δεόντως, ἐπεὶ καὶ τὰ καίρια ἐπαινεῖται. χρὴ μέντοι φιλεῖν τοὺς ἄξια φιλίας δρῶντας, πονηρὸς δ’ οὐδεὶς πρὸς ἀλήθειαν φίλος. συγγενεῖς δὲ καὶ ἐν συγγενέσι φίλους καλουμένους ἠλλοτρίωσαν αἱ μοχθηρίαι πλημμελοῦντας· συγγένεια γὰρ οἰκειοτέρα τῆς πρὸς αἵματος ἡ πρὸς δικαιοσύνην καὶ πᾶσαν ἀρετὴν ὁμολογία, ἣν ἐκλιπών τις οὐκ ἐν ὀθνείοις καὶ ξένοις μόνον ἀλλὰ καὶ ἐν ἀσπόνδοις ἐχθροῖς ἀναγράφεται.", "st": "155"}, {"sp": "N", "t": "τί οὖν κατεψευσμένον ὄνομα εὐνοίας ὅ τι χρηστὸν καὶ φιλάνθρωπόν ἐστιν ὑποδύεσθε, τἀληθῆ μαλακίαν καὶ ἀνανδρίαν παρακαλυπτόμενοι; ἢ οὐκ ἄνανδροι τὰς φύσεις, παρ’ οἷς οἴκτου λογισμὸς ἡττᾶται; καὶ ταῦθ’ ἵνα διπλοῦν ἀδίκημα δράσητε, τοὺς μὲν ὑπαιτίους ῥυόμενοι τῆς τιμωρίας, αὑτοὺς δ’ ἐπὶ μηδενὶ μεμφθέντας τὸ παράπαν", "st": "156"}, {"sp": "N", "t": "οἰόμενοι δεῖν ἀντ’ ἐκείνων κολάζειν;” ἀλλ’ οὗτοι μὲν ὑποτίμησιν ἔχουσι τὸ μηδὲν θηρᾶσθαι ἐπ’ ὠφελείᾳ καὶ τὸ λίαν πρὸς τοὺς ἐγγυτάτω γένους φιλόστοργον, ὑπὲρ ὧν τῆς σωτηρίας ἀποθνῄσκειν ἄσμενοι διανοοῦνται.", "st": "157"}, {"sp": "N", "t": "τοὺς δὲ ὠμοθύμους καὶ τὴν φύσιν θηριώδεις τίς οὐκ ἂν προβάλοιτο τῶν οὐ λέγω μετρίων ἀλλὰ καὶ τῶν μὴ σφόδρα ἀτιθάσων τὴν ψυχήν, οἳ ἢ λάθρα τεχνάζουσιν ἢ ἐπιθαρροῦσι φανερῶς ἑτέροις ἀνθ’ ἑτέρων τὰς μεγίστας ἐπανατείνεσθαι συμφοράς, φιλίαν ἢ συγγένειαν ἢ κοινωνίαν ἤ τι ὁμοιότροπον ἐπ’ ὀλέθρῳ τῶν οὐδὲν ἠδικηκότων προφασιζόμενοι; καὶ ταῦτα δρῶσιν ἔστιν ὅτε μηδὲν πεπονθότες δεινόν, ἕνεκα δὲ πλεονεξίας ἢ ἁρπαγῆς.", "st": "158"}, {"sp": "N", "t": "πρώην τις ἐκλογεὺς φόρων ταχθεὶς παρ’ ἡμῖν, ἐπειδή τινες τῶν δοξάντων ὀφείλειν διὰ πενίαν ἔφυγον δέει τιμωριῶν ἀνηκέστων, γύναια τούτων καὶ τέκνα καὶ γονεῖς καὶ τὴν ἄλλην γενεὰν ἀπαγαγὼν πρὸς βίαν, τύπτων καὶ προπηλακίζων καὶ πάσας αἰκίας αἰκιζόμενος, ἵν’ ἢ τὸν φυγόντα μηνύσωσιν ἢ τὰ ὑπὲρ ἐκείνου καταθῶσιν οὐδέτερον δυνάμενοι, τὸ μὲν ὅτι ἠγνόουν, τὸ δ’ ὅτι οὐχ ἧττον τοῦ φυγόντος ἀπόρως εἶχον, οὐ πρότερον ἀνῆκεν, ἢ βασάνοις καὶ στρέβλαις τὰ σώματα κατατείνων ἀποκτεῖναι κεκαινουργημέναις ἰδέαις θανάτου·", "st": "159"}, {"sp": "N", "t": "ἄμμου σπυρίδα πλήρη βρόχοις ἐκδησάμενος ἀνήρτα κατὰ τῶν αὐχένων, βαρύτατον ἄχθος, ἱστὰς ἐν ὑπαίθρῳ κατὰ μέσην ἀγοράν, ἵν’ οἱ μὲν ἀθρόαις τιμωρίαις, ἀνέμῳ καὶ ἡλίῳ καὶ τῇ ἀπὸ τῶν παριόντων αἰσχύνῃ καὶ τοῖς ἐκκρεμαμένοις ἄχθεσι, βιαζόμενοι χαλεπῶς ἀπαγορεύωσιν, οἱ δὲ θεώμενοι τὰς τούτων τιμωρίας προαλγῶσιν·", "st": "160"}, {"sp": "N", "t": "ὧν ἔνιοι τρανότερον τῆς διὰ τῶν ὀφθαλμῶν τὴν διὰ τῆς ψυχῆς λαβόντες αἴσθησιν, ὡς ἐν τοῖς ἑτέρων σώμασιν αὐτοὶ κακούμενοι, τῷ βίῳ προαπετάξαντο ξίφεσιν ἢ φαρμάκοις ἢ ἀγχόναις, μεγάλην ὡς ἐν κακοπραγίαις νομίζοντες ἐπιτυχίαν τὴν ἄνευ βασάνων τελευτήν·", "st": "161"}, {"sp": "N", "t": "οἱ δὲ μὴ φθάσαντες ἑαυτοὺς διαχρήσασθαι, καθάπερ ἐν ταῖς τῶν κλήρων ἐπιδικασίαις, κατὰ στοῖχον ἤγοντο οἱ ἀπὸ τοῦ γένους πρῶτοι καὶ μετ’ αὐτοὺς δεύτεροι καὶ τρίτοι μέχρι τῶν ὑστάτων· καὶ ὁπότε μηδεὶς λοιπὸς εἴη τῶν συγγενῶν, διέβαινε τὸ κακὸν καὶ ἐπὶ τοὺς γειτνιῶντας, ἔστι δ’ ὅτε καὶ ἐπὶ κώμας καὶ πόλεις, αἳ ταχέως ἔρημοι καὶ κεναὶ τῶν οἰκητόρων ἐγένοντο μετανισταμένων καὶ σκεδαννυμένων ἔνθα λήσεσθαι προσεδόκων.", "st": "162"}, {"sp": "N", "t": "ἀλλ’ οὐδὲν ἴσως θαυμαστόν, εἰ φορολογίας ἕνεκα βάρβαροι τὰς φύσεις, ἡμέρου παιδείας ἄγευστοι, δεσποτικοῖς πειθαρχοῦντες ἐπιτάγμασι τοὺς ἐτησίους ἀναπράττουσι δασμούς, οὐ μόνον ἐκ τῶν οὐσιῶν ἀλλὰ καὶ ἐκ τῶν σωμάτων, ἄχρι καὶ ψυχῆς τοὺς κινδύνους ἐπιφέροντες ὑπὲρ ἑτέρων ἑτέροις.", "st": "163"}, {"sp": "N", "t": "ἤδη δὲ καὶ οἱ τῶν δικαίων ὅροι καὶ κανόνες, αὐτοὶ οἱ νομοθέται, πρὸς δόξαν μᾶλλον ἢ πρὸς ἀλήθειαν ἀπιδόντες, τῶν ἀδικωτάτων ὑπέμειναν γενέσθαι, κελεύσαντες τοῖς μὲν προδόταις τοὺς παῖδας συναναιρεῖσθαι, τοῖς δὲ τυράννοις τὰς ἐγγυτάτω πέντε οἰκίας. διὰ τί;", "st": "164"}, {"sp": "N", "t": "φαίην ἄν· εἰ μὲν γὰρ συνεξήμαρτον, καὶ συγκολαζέσθωσαν, εἰ δὲ μήτε κατεκοινώνησαν μήτε ζηλωταὶ τῶν ὁμοίων ἐγένοντο μήτε ταῖς τῶν οἰκείων εὐτυχίαις ἐπαρθέντες ἐνηδυπάθησαν, τίνος χάριν ἀναιρεθήσονται; ἢ δι’ ἓν τοῦτο μόνον, ὅτι συγγενεῖς εἰσι; γένους γὰρ ἢ παρανομημάτων αἱ τιμωρίαι;", "st": "165"}, {"sp": "N", "t": "χρηστῶν ἴσως ὑμεῖς, ὦ σεμνοὶ νομοθέται, τῶν οἰκείων ἐλάχετε· μοχθηροὶ δ’ εἴπερ ἐγένοντο, δοκεῖτέ μοι μηδ’ ἂν εἰς νοῦν ποτε βαλέσθαι τὰς τοιαύτας προστάξεις, ἀλλὰ καὶ γράφοντας ἑτέρους δυσχερᾶναι, διὰ τὴν τοῦ μηδὲν ἀνήκεστον παθεῖν προφυλακὴν * * * τὸν ἐν ἀσφαλεῖ βίῳ διάγοντα μετὰ τῶν κινδυνευόντων σκοπεῖν καὶ ἐν ταῖς ἴσαις κακοπραγίαις ἐξετάζεσθαι· τὸ μὲν γὰρ ἔχει δέος, ὃ φυλαττόμενός τις οὐδ’ ἂν ἕτερον περιΐδοι, τὸ δ’ ἐστὶν ἄφοβον, ὑφ’ οὗ πολλάκις ἀνεπείσθησάν τινες ἀλογεῖν ἀνθρώπων ἀνυπαιτίων ἀσφαλείας.", "st": "166"}, {"sp": "N", "t": "ταῦτ’ οὖν ἐκλογισάμενος ὁ ἡμέτερος νομοθέτης καὶ τὰ παρὰ τοῖς ἄλλοις ἁμαρτήματα συνιδὼν ὡς φθοροποιὰ τῆς ἀρίστης πολιτείας ἀπεστράφη καὶ διεμίσησε [καὶ] τοὺς χρωμένους εἴτε ῥᾳθυμίαις εἴτε ἀπανθρωπίαις καὶ κακίαις καὶ οὐδέποτέ τινα τῶν συμβεβιωκότων ἐξέδωκεν ἐπὶ τιμωρίᾳ προσθήκην ποιησάμενος αὐτὸν ἀδικημάτων ἑτέρων.", "st": "167"}, {"sp": "N", "t": "διόπερ ἄντικρυς ἀπεῖπεν υἱοὺς ἀντὶ γονέων ἢ γονεῖς ἀντὶ υἱῶν ἀναιρεῖσθαι, δικαιώσας ὧν τὰ ἁμαρτήματα τούτων εἶναι καὶ τὰς τιμωρίας, εἴτε ζημίας χρημάτων εἴτε καὶ πληγὰς καὶ βιαιοτέρας ὕβρεις εἴτε τραύματα καὶ πηρώσεις καὶ ἀτιμίας καὶ φυγὰς καὶ ὅσα ἄλλα τῶν ἐπὶ δίκαις· ἑνὸς γὰρ τοῦ μὴ ἕτερον ἀνθ’ ἑτέρου κτείνειν μνησθεὶς καὶ τὰ ἡσυχασθέντα προσπεριέλαβεν.", "st": "168"}, {"sp": "N", "t": "Ἀγοραὶ καὶ βουλευτήρια καὶ δικαστήρια καὶ θίασοι καὶ σύλλογοι πολυανθρώπων ὁμίλων καὶ ὁ ἐν ὑπαίθρῳ βίος διὰ λόγων καὶ πράξεων κατὰ πολέμους καὶ κατ’ εἰρήνην ἀνδράσιν ἐφαρμόζουσι, θηλείαις δὲ οἰκουρία καὶ ἡ ἔνδον μονή, παρθένοις μὲν εἴσω κλισιάδων τὴν μέσαυλον ὅρον πεποιημέναις, τελείαις δὲ ἤδη γυναιξὶ τὴν αὔλειον.", "st": "169"}, {"sp": "N", "t": "διττὸν γὰρ πόλεων εἶδος, μειζόνων καὶ βραχυτέρων· αἱ μὲν οὖν μείζους ἄστη καλοῦνται, οἰκίαι δ’ αἱ βραχύτεραι. τὴν δ’ ἑκατέρων προστασίαν διειλήχασιν ἄνδρες μὲν τῶν μειζόνων, ἧς ὄνομα πολιτεία, γυναῖκες δὲ τῶν βραχυτέρων, ἧς ὄνομα οἰκονομία.", "st": "170"}, {"sp": "N", "t": "μηδὲν οὖν ἔξω τῶν κατὰ τὴν οἰκονομίαν πολυπραγμονείτω γυνὴ ζητοῦσα μοναυλίαν μηδ’ οἷα νομὰς κατὰ τὰς ὁδοὺς ἐν ὄψεσιν ἀνδρῶν ἑτέρων ἐξεταζέσθω, πλὴν εἰς ἱερὸν ὁπότε δέοι βαδίζειν, φροντίδα ποιουμένη καὶ τότε μὴ πληθυούσης ἀγορᾶς, ἀλλ’ ἐπανεληλυθότων οἴκαδε τῶν πλείστων, ἐλευθέρας τρόπον καὶ τῷ ὄντι ἀστῆς ἐν ἠρεμίᾳ θυσίας ἐπιτελοῦσα καὶ εὐχὰς εἰς ἀποτροπὴν κακῶν καὶ μετουσίαν ἀγαθῶν.", "st": "171"}, {"sp": "N", "t": "τὸ δὲ λοιδορουμένων ἢ συμπλεκομένων ἀνδρῶν ἐπεκθεῖν τολμᾶν κατὰ πρόφασιν συμμαχίας ἢ βοηθείας γυναῖκας ἐπίληπτον καὶ οὐ μετρίως ἀναίσχυντον, ἃς οὐδ’ ἐν πολέμοις καὶ στρατείαις καὶ τοῖς ὑπὲρ πάσης τῆς πατρίδος κινδύνοις ἐδικαίωσεν ὁ νόμος ἐξετάζεσθαι, τὸ πρέπον ἰδών, ὅπερ ἀκίνητον ἀεὶ καὶ πανταχοῦ φυλάττειν διενοήθη, νομίσας αὐτὸ τοῦτ’ εἶναι καθ’ αὑτὸ νίκης καὶ ἐλευθερίας καὶ πάσης ἄμεινον εὐτυχίας.", "st": "172"}, {"sp": "N", "t": "ἐὰν μέντοι καὶ πυθομένη τις ὑβρίζεσθαι τὸν ἄνδρα, πόθῳ τῷ πρὸς ἐκεῖνον ἡττηθεῖσα φιλανδρίας, ὑπὸ τοῦ παραστάντος πάθους ἐξορμῆσαι βιασθῇ, μὴ πλέον τῆς φύσεως ἀρρενούσθω θρασυνομένη, μενέτω δὲ καὶ ἐν οἷς βοηθεῖ γυνή· πάνδεινον γάρ, εἰ βουλομένη τις ὑπεξελέσθαι τὸν ἄνδρα ὕβρεως ὑβρισθήσεται πρὸς ἑαυτῆς κατάπλεων ἀποφαινούσης τὸν ἴδιον βίον αἰσχύνης καὶ μεγάλων ὀνειδῶν τῶν ἐπ’ ἀνιάτῳ θρασύτητι.", "st": "173"}, {"sp": "N", "t": "λοιδορήσεται γὰρ γυνὴ κατ’ ἀγορὰν ῥῆμά τέ τι τῶν ἀπηγορευμένων φθέγξεται, ἑτέρου δὲ κακηγοροῦντος οὐκ ἀποδραμεῖται τὰ ὦτα ἐπιφράξασα; νυνὶ δὲ προβαίνουσί τινες, ὡς μὴ μόνον ὑπὸ γλωσσαλγίας ἐν ἀνδρῶν ὄχλῳ [γυναῖκες] κακηγορεῖν καὶ προπηλακίζειν, ἀλλὰ καὶ τὰς χεῖρας ἐπιφέρειν τὰς ὑφάσμασι καὶ ταλασίαις ἀλλ’ οὐ πληγαῖς καὶ ὕβρεσι καθάπερ παγκρατιαστῶν καὶ πυκτῶν ἐνασκουμένας.", "st": "174"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλα [οἰστὰ καὶ] φέρειν ἄν τις δύναιτο· χαλεπὸν δ’ ἐκεῖνο, εἴ τις γυνὴ τοσοῦτον καταθρασύνοιτο, ὡς διαδράξασθαι τῶν τοῦ διαφερομένου γεννητικῶν· μὴ γάρ, παρόσον ἀνδρὶ βοηθοῦσα δοκεῖ τοῦτο πράττειν, ἀφείσθω, τῆς δ’ ἄγαν θρασύτητος ἐπεχέσθω τίνουσα δίκην, ὑφ’ ἧς αὐτὴ μὲν τὰ ὅμοια ἐξαμαρτάνειν ἐθέλουσα αὖθις οὐκ ἂν δύναιτο, τῶν δ’ ἄλλων ὅσαι προπετέστεραι φόβῳ μετριάσουσιν· ἔστω δ’ ἡ δίκη χειρὸς ἀποκοπὴ τῆς ἁψαμένης ὧν οὐ θέμις.", "st": "175"}, {"sp": "N", "t": "ἄξιον ἐπαινεῖν καὶ τοὺς τῶν γυμνικῶν ἀγώνων ἀθλοθέτας, οἳ τῆς θέας ἀνεῖρξαν γυναῖκας, ἵνα μὴ γυμνουμένοις ἀνδράσι παρατυγχάνουσαι τὸ δόκιμον αἰδοῦς νόμισμα παρακόπτωσιν ἀλογοῦσαι φύσεως θεσμῶν, οὓς ὥρισεν ἑκατέρῳ τμήματι τοῦ γένους ἡμῶν. οὐδὲ γὰρ ἄνδρας, ἀποτιθεμένων ἐσθῆτας γυναικῶν, ἐμπρεπὲς παρατυγχάνειν, ἀλλ’ ἑκατέρους τὰς τῶν ἑτέρων ὄψεις ἐκτρέπεσθαι γυμνουμένων τοῖς τῆς φύσεως βουλήμασιν ἑπομένους.", "st": "176"}, {"sp": "N", "t": "εἶθ’ ὧν ἡ ὄψις ἐπίληπτος, οὐ πολὺ μᾶλλον αἱ χεῖρες ὑπαίτιοι; ὀφθαλμοὶ μὲν γὰρ καὶ ἃ μὴ βουλόμεθα πολλάκις ὁρᾶν ἀπελευθεριάζοντες ἀποβιάζονται, χεῖρες δ’ ἐν τῇ τῶν ὑπηκόων τάξει τεταγμέναι μερῶν πειθαρχοῦσαι τοῖς ἡμετέροις ἐπιτάγμασιν ὑπηρετοῦσιν.", "st": "177"}, {"sp": "N", "t": "ἥδε μὲν αἰτία ἣ παρὰ πολλοῖς εἴωθε λέγεσθαι· ἑτέραν δὲ ἤκουσα θεσπεσίων ἀνδρῶν τὰ πλεῖστα τῶν ἐν τοῖς νόμοις ὑπολαμβανόντων εἶναι σύμβολα φανερὰ ἀφανῶν καὶ ῥητὰ ἀρρήτων. ἦν δὲ τοιάδε· ψυχῆς, ὥσπερ ἐν ταῖς συγγενείαις, ἡ μέν ἐστιν ἄρρην καὶ πρὸς ἀνδρῶν, ἡ δὲ θήλεια καὶ πρὸς γυναικῶν· ἄρρην μὲν ἡ μόνῳ θεῷ προσκληροῦσα ἑαυτὴν ὡς πατρὶ καὶ ποιητῇ τῶν ὅλων καὶ πάντων αἰτίῳ, θήλεια δὲ ἡ ἐκκρεμαμένη τῶν ἐν γενέσει καὶ φθορᾷ καὶ ἀποτείνουσα καθάπερ χεῖρα τὴν δύναμιν αὑτῆς, ἵνα τυφλῶς τῶν ἐπιτυχόντων ἐφάπτηται, γένεσιν δεξιουμένη τὴν τροπαῖς ἀμυθήτοις χρωμένην καὶ μεταβολαῖς, δέον τὴν ἀμετάβλητον καὶ μακαρίαν καὶ τρισευδαίμονα θείαν φύσιν.", "st": "178"}, {"sp": "N", "t": "εἰκότως οὖν τὴν ἐφαψαμένην χεῖρα τῶν διδύμων ἀποκόπτειν διείρηται συμβολικῶς, οὐχ ὅπως ἀκρωτηριάζηται τὸ σῶμα στερόμενον ἀναγκαιοτάτου μέρους, ἀλλ’ ὑπὲρ τοῦ τῆς ψυχῆς πάντας τοὺς ἀθέους ἐκτέμνειν λογισμοὺς ἐπιβάθρᾳ χρωμένους ἅπασιν ὧν γένεσίς ἐστι· δίδυμοι γὰρ σύμβολον σπορᾶς καὶ γενέσεως.", "st": "179"}, {"sp": "N", "t": "ἑπόμενος δ’ ἀκολουθίᾳ φύσεως κἀκεῖνο λέξω, ὅτι μονὰς μέν ἐστιν εἰκὼν αἰτίου πρώτου, δυὰς δὲ παθητῆς καὶ διαιρετῆς ὕλης· ὃς ἂν οὖν δυάδα πρὸ μονάδος τιμήσῃ καὶ δεξιώσηται, μὴ ἀγνοείτω τὴν ὕλην ἀποδεχόμενος μᾶλλον ἢ θεόν. ἧς χάριν αἰτίας ἐδικαίωσεν ὁ νόμος ταύτην τὴν ἐπιβολὴν τῆς ψυχῆς ἀποκόπτειν οἷα χεῖρα· μεῖζον γὰρ οὐκ ἔστιν ἀσέβημα ἢ τῷ παθητῷ τὴν τοῦ δρῶντος ἀνατιθέναι δύναμιν.", "st": "180"}, {"sp": "N", "t": "Μέμψαιτ’ ἄν τις δεόντως τοὺς ἀνόμοια τοῖς ἀδικήμασι τάττοντας ἐπιτίμια κατὰ τῶν εἰργασμένων, ζημίας χρημάτων ἐπ’ αἰκίαις ἢ ἐπὶ τραύμασι καὶ πηρώσεσιν ἀτιμίας ἢ ἐπ’ ἀνδροφονίαις ἑκουσίοις ἐλάσεις ὑπερορίους καὶ τὰς εἰς ἀεὶ φυγὰς ἢ δεσμοὺς ἐπὶ κλοπαῖς· τὸ γὰρ ἀνώμαλον καὶ ἄνισον ἐχθρὸν πολιτείας ζηλούσης τὴν ἀλήθειαν.", "st": "181"}, {"sp": "N", "t": "ἰσότητος δὲ ὑφηγητὴς ὁ ἡμέτερος νόμος τὰ ὅμοια κελεύων τοὺς ἁμαρτάνοντας ὑπομένειν οἷς ἔδρασαν, ἐκ τῶν οὐσιῶν, ἐὰν περὶ τὰς οὐσίας ἀδικοπραγῶσι τῶν πλησίον, ἐκ τῶν σωμάτων, ἐὰν εἰς τὰ σώματα ἐξαμαρτάνωσι κατὰ μέρη καὶ μέλη καὶ τὰς αἰσθήσεις· κἂν ἄχρι μέντοι τῆς ψυχῆς ἐπιβουλεύσωσιν, εἰς ψυχὴν τιμωρεῖσθαι κελεύει· ὑπομένειν γὰρ ἀνθ’ ἑτέρων ἕτερα μηδεμίαν ἔχοντα κοινωνίαν ἀλλὰ τοῖς εἴδεσιν ἀπηρτημένα καταλυόντων νόμους ἐστίν, οὐ βεβαιούντων.", "st": "182"}, {"sp": "N", "t": "ταυτὶ δέ φαμεν τῶν ἄλλων [οὐχ] ὁμοίως ἐχόντων· οὐ γὰρ ταὐτὸν ἀλλοτρίῳ καὶ πατρὶ πληγὰς ἐμφορῆσαι οὐδὲ ἄρχοντα ἢ ἰδιώτην κακῶς εἰπεῖν οὐδὲ ἐργάσασθαί τι τῶν μὴ ἐφειμένων ἐν βεβήλοις ἢ ἱεροῖς χωρίοις οὐδ’ ἐν ἑορταῖς καὶ πανηγύρεσι καὶ δημοτελέσι θυσίαις καὶ πάλιν ἐν ἡμέραις αἷς μηδὲν πρόσεστι τῶν εἰς ἐκεχειρίαν ἢ καὶ συνόλως ἀποφράσι, καὶ ὅσα ἄλλα τοιουτότροπα διερευνητέον εἰς συναύξησιν ἢ μείωσιν κολάσεως.", "st": "183"}, {"sp": "N", "t": "Πάλιν ἐάν τις, φησίν, ὀφθαλμὸν οἰκέτου ἢ θεραπαίνης ἐκκόψῃ, ἐλευθέρους ἀφιέτω. διὰ τί; ὥσπερ τὴν τοῦ σώματος ἡγεμονίαν ἡ φύσις ἀνῆψε κεφαλῇ χαρισαμένη καὶ τόπον οἰκειότατον ὡς βασιλεῖ τὴν ἄκραν—ἄνω γὰρ αὐτὴν ἐπ’ ἀρχὴν παραπέμψασα ἱδρύσατο καθάπερ ἀνδριάντι βάσιν ὑποθεῖσα τὴν ἀπ’ αὐχένος ἄχρι ποδῶν ἅπασαν ἁρμονίαν—, οὕτως καὶ τῶν αἰσθήσεων τὸ κράτος ἀνέδωκεν ὀφθαλμοῖς· ὑπεράνω γοῦν καὶ τούτοις ὡς ἄρχουσιν ἀπένειμεν οἴκησιν, βουληθεῖσα μὴ μόνον τοῖς ἄλλοις ἀλλὰ καὶ χωρίῳ περισημοτάτῳ καὶ περιφανεστάτῳ τούτους γερᾶραι.", "st": "184"}, {"sp": "N", "t": "τὰς μὲν οὖν χρείας καὶ ὠφελείας, ἃς παρέχουσι τῷ γένει ἡμῶν ὀφθαλμοί, μακρὸν ἂν εἴη καταριθμεῖσθαι· μίαν δὲ τὴν ἀρίστην λεκτέον. φιλοσοφίαν ὤμβρησε μὲν ὁ οὐρανός, ἐχώρησε δὲ ὁ ἀνθρώπινος νοῦς, ἐξενάγησε δὲ ὄψις· πρώτη γὰρ αὕτη κατεῖδε τὰς λεωφόρους ἐπ’ αἰθέρος ὁδούς.", "st": "185"}, {"sp": "N", "t": "ἀγαθῶν δέ, ὅσα πρὸς ἀλήθειαν ἀγαθά, πηγὴ φιλοσοφία· ἧς ὁ μὲν ἀρυτόμενος εἰς κτῆσιν καὶ χρῆσιν ἀρετῆς ἐπαινετός, ὁ δ’ ἕνεκα πανουργίας καὶ τοῦ κατασοφίσασθαί τινα ψεκτός· ἔοικε γὰρ ὁ μὲν ἀνδρὶ συμποτικῷ καὶ ἑαυτὸν καὶ τοὺς συνεστιωμένους πάντας εὐφραίνοντι, ὁ δὲ τῷ τὸν ἄκρατον εἰς παροινίαν καὶ ὕβριν ἑαυτοῦ τε καὶ τῶν πλησίον ἐμφορουμένῳ.", "st": "186"}, {"sp": "N", "t": "ὅτῳ δ’ οὖν τρόπῳ φιλοσοφίαν ἐξενάγησεν ὄψις, ἤδη λεκτέον. ἀναβλέψασα εἰς αἰθέρα κατεῖδεν ἥλιον καὶ σελήνην καὶ πλάνητας καὶ ἀπλανεῖς ἀστέρας, τὴν ἱεροπρεπεστάτην οὐρανοῦ στρατιάν, κόσμον ἐν κόσμῳ, εἶτ’ ἀνατολὰς καὶ δύσεις καὶ χορείας ἐμμελεῖς καὶ τεταγμέναις χρόνων περιόδοις συνόδους, ἐκλείψεις, ἐπιλάμψεις,", "st": "187"}, {"sp": "N", "t": "εἶτ’ αὐξήσεις καὶ μειώσεις σελήνης, ἡλίου κινήσεις τὰς κατὰ πλάτος, ἀπὸ μὲν τῶν νοτίων ἐπὶ τὰ βόρεια προσιόντος, ἀπὸ δὲ τῶν βορείων ἐξαναχωροῦντος πρὸς τὰ νότια, εἰς καιρῶν τῶν ἐτησίων γένεσιν, οἷς τὰ πάντα τελεσφορεῖται, καὶ πρὸς τούτοις μυρία ἄλλα θαυμάσια· καὶ περιαθρήσασα κατά τε γῆν καὶ κατὰ θάλατταν καὶ ἀέρα τάδε πάντα τῷ νῷ μετὰ σπουδῆς ἐπεδείξατο.", "st": "188"}, {"sp": "N", "t": "ὁ δ’ ἅπερ οὐχ οἷός τ’ ἦν δι’ αὑτοῦ καταλαβεῖν διὰ τῆς ὁράσεως ἰδὼν οὐκ ἐπὶ τῶν ὁραθέντων αὐτὸ μόνον ἔστη, ἀλλ’ ἅτε φιλομαθὴς καὶ φιλόκαλος, ἀγάμενος τὴν θέαν, λογισμὸν εἰκότα ἐλάμβανεν, ὅτι ταῦτα οὐκ ἀπαυτοματισθέντα συνέστη φοραῖς ἀλόγοις, ἀλλὰ διανοίᾳ θεοῦ, ὃν πατέρα καὶ ποιητὴν ὀνομάζειν θέμις, καὶ ὅτι οὐκ ἔστιν ἄπειρα, πεπέρασται δὲ ἑνὸς κόσμου περιγραφῇ, πόλεως τρόπον τῇ τῶν ἀπλανῶν ἐξωτάτω σφαίρᾳ περιλαμβανόμενα, καὶ ὡς ὁ γεννήσας πατὴρ νόμῳ φύσεως ἐπιμελεῖται τοῦ γενομένου, προνοούμενος καὶ τοῦ ὅλου καὶ τῶν μερῶν.", "st": "189"}, {"sp": "N", "t": "εἶτα προσεπεσκέψατο, τίς οὐσία τοῦ ὁρατοῦ καὶ εἰ πάντων ἡ αὐτὴ τῶν κατὰ τὸν κόσμον ἢ ἑτέρων ἑτέρα καὶ ἐκ τίνων ἕκαστα ἐτελέσθη, καὶ τὰς αἰτίας δι’ ἃς ἐγένετο καὶ δυνάμεις αἷς συνέχεται καὶ πότερον αὗται σώματα ἢ ἀσώματοι.", "st": "190"}, {"sp": "N", "t": "ἡ γὰρ περὶ τούτων καὶ τῶν παραπλησίων ἔρευνα τί ἂν ἄλλο ἢ φιλοσοφία προσαγορεύοιτο; τί δὲ τῷ σκοπουμένῳ ταῦτα θεῖτο ἄν τις οἰκειότερον ὄνομα ἢ φιλόσοφον; τὸ γὰρ περὶ θεοῦ σκοπεῖν καὶ κόσμου καὶ τῶν ἐν αὐτῷ κοινῶς ζῴων τε καὶ φυτῶν καὶ περὶ νοητῶν παραδειγμάτων καὶ πάλιν αἰσθητῶν ἀποτελεσμάτων καὶ τῆς καθ’ ἕκαστον τῶν γεγονότων ἀρετῆς τε καὶ κακίας φιλομαθῆ καὶ φιλοθεάμονα καὶ τῷ ὄντι φιλόσοφον διάθεσιν ἐμφαίνει.", "st": "191"}, {"sp": "N", "t": "μέγιστον μὲν δὴ τοῦτο τῷ βίῳ τῶν ἀνθρώπων ἀγαθὸν ὄψις παρέχεται· δοκεῖ δέ μοι ταύτης ἠξιῶσθαι τῆς προνομίας, ἐπειδὴ τῶν ἄλλων αἰσθήσεων συγγενεστέρα ψυχῇ καθέστηκεν· ἅπασαι μὲν γὰρ τὴν πρὸς διάνοιαν ἔχουσιν οἰκειότητα, αὕτη δὲ καθάπερ ἐν ταῖς οἰκίαις τὴν ἐγγυτάτω γένους πρώτην καὶ ἀνωτάτω τάξιν εἴληχε.", "st": "192"}, {"sp": "N", "t": "τεκμηριώσαιτο δ’ ἄν τις ἐκ πολλῶν· τίς γὰρ οὐκ οἶδεν, ὅτι χαιρόντων μὲν ὀφθαλμοὶ γανοῦνται καὶ μειδιῶσι, λυπουμένων δὲ συννοίας γέμουσι καὶ κατηφείας; εἰ δὲ πλεονάζοι καὶ πιέζοι καὶ ἀναθλίβοι τὸ ἄχθος, ἐκδακρύουσι καὶ κρατούσης μὲν ὀργῆς οἰδοῦσι καὶ ὕφαιμον καὶ πυρωπὸν ἐμβλέπουσιν, ἵλεων δὲ καὶ εὐμενές, εἰ χαλάσαι ὁ θυμός.", "st": "193"}, {"sp": "N", "t": "καὶ ἐν μὲν τῷ λογίζεσθαι καὶ σκοπεῖν αἱ κόραι πεπήγασι τρόπον τινὰ συνεννοοῦσαι, τῶν δὲ εὐηθεστέρων ὑπ’ ἠλιθιότητος πλάζεται καὶ ἡ ὅρασις οὐκ ἠρεμοῦσα· καὶ συνόλως τοῖς τῆς ψυχῆς πάθεσι συμπάσχουσιν ὀφθαλμοὶ καὶ ταῖς ἀμυθήτοις τροπαῖς συμμεταβάλλειν πεφύκασι διὰ τὴν οἰκειότητα· δοκεῖ γάρ μοι μηδὲν οὕτως ὁ θεὸς ἐμφανὲς ἀφανοῦς ἀπεργάσασθαι μίμημα", "st": "194"}, {"sp": "N", "t": "ὡς ὄψιν λογισμοῦ. ἐάν τις οὖν εἰς τὴν ἀρίστην καὶ ἡγεμονικωτάτην τῶν αἰσθήσεων ὅρασιν ᾖ ἐπιβεβουλευκώς τῳ καὶ καταφανῇ μὲν ἐλευθέρου ὀφθαλμὸν ἐκκόψας, τὰ αὐτὰ ἀντιπασχέτω, δούλου δὲ μή· οὐχ ὅτι συγγνώμης ἐστὶν ἄξιος ἢ ἔλαττον ἀδικεῖ, ἀλλ’ ὅτι πονηροτέρῳ χρήσαιτ’ ἂν ὁ πεπονθὼς ἀντιπηρωθέντι τῷ δεσπότῃ, μνησικακήσοντι τῆς συμφορᾶς τὸν ἀεὶ χρόνον καὶ ἀμυνουμένῳ καθ’ ἑκάστην ἡμέραν ὡς ἐχθρὸν ἄσπονδον ἀφορήτοις καὶ βαρυτέροις τῆς δυνάμεως ἐπιτάγμασιν, οἷς πιεζόμενος καὶ τὴν ψυχὴν ἀπορρήξει.", "st": "195"}, {"sp": "N", "t": "προὐνόησεν οὖν ὁ νόμος τοῦ μήτε τὸν ἐπιβεβουλευκότα ἀθῷον ἀφεθῆναι μήτε τὸν πεπηρωμένον προσαδικηθῆναι κελεύσας, εἴ τις ἐκκόψειε θεράποντος ὀφθαλμόν, ἀνενδοιάστως ἐλευθερίας μεταδιδόναι.", "st": "196"}, {"sp": "N", "t": "οὕτως γὰρ ὁ μὲν ἀνθ’ ὧν ἔδρασε διττὴν ἐνδέξεται ζημίαν, ἅμα τῇ τιμῇ καὶ τὴν ὑπηρεσίαν ἀφαιρεθείς, καὶ τρίτον ἑκατέρου τῶν λεχθέντων χαλεπώτερον, ἀναγκαζόμενος ἐν τοῖς μεγίστοις εὐεργετεῖν ἐχθρόν, ὃν ἴσως ηὔχετο κακοῦν ἀεὶ δύνασθαι, ὁ δὲ ἀνθ’ ὧν ὑπέμεινε παρηγορίαν ἕξει διπλῆν, οὐ μόνον ἐλευθερωθεὶς ἀλλὰ καὶ ἀργαλέον καὶ ὠμὸν δεσπότην ἐκφυγών.", "st": "197"}, {"sp": "N", "t": "Προστάττει δὲ κἂν εἴ τις ὀδόντα θεράποντος ἐκκόψειεν, ἐλευθερίαν χαρίζεσθαι τῷ θεράποντι. διὰ τί; ὅτι ζωὴ μὲν τίμιον, ὄργανα δὲ ζωῆς ἐτεκτήνατο ἡ φύσις ὀδόντας, οἷς τὴν τροφὴν οἰκονομεῖσθαι συμβέβηκεν. ὀδόντες δὲ οἱ μέν εἰσι τομίαι τῷ τέμνειν σιτία καὶ ὅσα ἄλλα ἐδώδιμα, διὰ τοῦτο ταύτης τῆς προσηγορίας ἀξιωθέντες, οἱ δὲ μύλαι τῷ τὰ διατμηθέντα εἰς μείονα λεαίνειν δύνασθαι.", "st": "198"}, {"sp": "N", "t": "παρ’ ἣν αἰτίαν ὁ ποιητὴς καὶ πατὴρ οὐδὲν εἰωθὼς δημιουργεῖν, ὃ μὴ πρός τινι τέτακται χρείᾳ, τοὺς ὀδόντας οὐχ ὥσπερ τῶν ἄλλων μερῶν ἕκαστον κατὰ τὴν πρώτην γένεσιν εὐθὺς εἰργάζετο, διανοηθεὶς ὅτι βρέφει μὲν γαλακτοτροφεῖσθαι μέλλοντι περιττὸν ἄχθος γενήσονται, μαστοῖς δὲ πηγάζουσιν, οἷς ἄρδεται ἡ τροφή, χαλεπὴ ζημία κατὰ τὴν ὁλκὴν τοῦ γάλακτος ὀδαξωμένοις.", "st": "199"}, {"sp": "N", "t": "τὸν ἐπιτήδειον οὖν καιρὸν προϊδόμενος—ἔστι δ’ οὗτος, ἡνίκα τὸ βρέφος ἀπότιτθον γίνεται—τὴν ἔκφυσιν τῶν ὀδόντων, ἣν ἐταμιεύσατο πρότερον, ἀνέφηνεν, ὅτε δύναται ἤδη τῆς τελειοτέρας ἀνέχεσθαι τροφῆς ὀργάνων ὧν εἶπον δεομένης τὴν διὰ τοῦ γάλακτος ἀποστρεφόμενον.", "st": "200"}, {"sp": "N", "t": "ἐὰν οὖν τις εἴξας ἀλαζονείᾳ θεράποντος ὀδόντα ἐκκόψῃ τὸν ὑπηρέτην καὶ ὑποδιάκονον τῶν ἀναγκαιοτάτων, τροφῆς τε καὶ ζωῆς, ἐλευθερούτω τὸν ἀδικηθέντα, στερόμενος καὶ αὐτὸς τῆς ἐκ τοῦ πεπονθότος λατρείας τε καὶ ὑπηρεσίας.", "st": "201"}, {"sp": "N", "t": "ἰσότιμον οὖν, φήσει τις, ὀδοὺς ὀφθαλμῷ; πρὸς ἃ γέγονεν ἑκάτερον, εἴποιμ’ ἄν, ἰσότιμον, πρὸς μὲν τὰ ὁρατὰ ὀφθαλμός, πρὸς δὲ τὰ ἐδώδιμα ὀδούς. εἰ δὲ καὶ συγκρῖναί τις ἐθελήσει, σεμνότατον μὲν εὑρήσει τῶν ἐν σώματι μερῶν ὀφθαλμὸν ἅτε θεωρὸν ὄντα τοῦ σεμνοτάτου τῶν κατὰ τὸν κόσμον, οὐρανοῦ, χρήσιμον δὲ ὀδόντα ὡς ἂν τροφῆς, τοῦ χρησιμωτάτου πρὸς τὸ ζῆν, ἐργάτην· καὶ ὁ μὲν τὰς ὄψεις ἀποβαλὼν οὐ κεκώλυται βιοῦν, τῷ δὲ ἐκκοπέντι τοὺς ὀδόντας ἐφεδρεύει θάνατος οἴκτιστος.", "st": "202"}, {"sp": "N", "t": "εἰ δή τις ἐπιβουλεύει περὶ τὰ μέρη ταῦτα τοῖς οἰκέταις, μὴ ἀγνοείτω λιμὸν ἐν εὐθηνίᾳ καὶ εὐετηρίᾳ κατασκευάζων τούτοις χειροποίητον· τί γὰρ ὄφελος ἀφθονίαν μὲν εἶναι τροφῶν, τὰ δὲ πρὸς τὴν διοίκησιν αὐτῶν ὄργανα σεσυλῆσθαι καὶ ἀποβεβληκέναι χαλεπῶν ἕνεκα καὶ ἀμειλίκτων καὶ ὠμοθύμων δεσποτῶν;", "st": "203"}, {"sp": "N", "t": "διὰ τοῦτο καὶ ἑτέρωθι παρὰ χρεωστῶν ἀπαγορεύει δανεισταῖς μύλον ἢ ἐπιμύλιον ῥύσιον αἰτεῖν, ἐπειπὼν ὅτι ὁ τοῦτο δρῶν ψυχὴν ἐνεχυριάζει· ὁ γὰρ τὰ τοῦ ζῆν ὄργανα ἀφαιρούμενος ἐπ’ ἀνδροφονίαν ἵεται, μέχρι καὶ ψυχῆς ἐπιβουλεύειν διανοηθείς.", "st": "204"}, {"sp": "N", "t": "Τοσαύτην δὲ πρόνοιαν ἐποιήσατο τοῦ μηδένα παραίτιόν τινι γενέσθαι θανάτου, ὡς καὶ τοὺς προσαψαμένους νεκροῦ σώματος, ὃ τελευτὴν ἐνδέδεκται τὴν κατὰ φύσιν, οἴεται δεῖν μὴ εὐθὺς εἶναι καθαρούς, μέχρις ἂν περιρρανάμενοι καὶ ἀπολουσάμενοι καθαρθῶσιν. εἰς μέντοι τὸ ἱερὸν οὐδὲ τοῖς σφόδρα καθαροῖς ἐφῆκεν εἰσιέναι ἐντὸς ἡμερῶν ἑπτά, τρίτῃ καὶ ἑβδόμῃ κελεύσας ἀφαγνίζεσθαι.", "st": "205"}, {"sp": "N", "t": "ἔτι μέντοι καὶ τοῖς εἰσιοῦσιν εἰς οἰκίαν, ἐν ᾗ τετελεύτηκέ τις, προστάττει μηδενὸς ἅπτεσθαι, μέχρις ἂν ἀπολούσωνται καὶ τὰς ἐσθῆτας αἷς ἀμπίσχοντο προσαποπλύναντες· σκεύη δὲ καὶ ἔπιπλα καὶ ὅσα ἄλλα ἔνδον εἶναι συμβέβηκε πάνθ’ ὡς ἔπος εἰπεῖν ἀκάθαρτα ἡγεῖται.", "st": "206"}, {"sp": "N", "t": "ψυχὴ γὰρ ἀνθρώπου τίμιον, ἧς μετανισταμένης καὶ μετοικιζομένης τὰ ἀπολειφθησόμενα πάντα μιαίνεται στερόμενα θείας εἰκόνος, ἐπειδὴ θεοειδὴς ὁ ἀνθρώπινος νοῦς πρὸς ἀρχέτυπον ἰδέαν, τὸν ἀνωτάτω λόγον, τυπωθείς.", "st": "207"}, {"sp": "N", "t": "ἔστω δέ, φησίν, ἀκάθαρτα καὶ τὰ ἄλλα ὅσων ἂν ὁ ἀκάθαρτος προσάψηται, μετουσίᾳ τοῦ μὴ καθαροῦ μιαινόμενα. καθολικωτέραν δ’ ἀπόφασιν ὁ χρησμὸς οὗτος ἔοικέ πως δηλοῦν, οὐκ ἐπὶ σώματος αὐτὸ μόνον ἱστάμενος, ἀλλὰ ἤθη καὶ τρόπους προσδιερευνώμενος ψυχῆς.", "st": "208"}, {"sp": "N", "t": "ἀκάθαρτος γὰρ κυρίως ὁ ἄδικος καὶ ἀσεβής, ὅτῳ μήτε τῶν ἀνθρωπίνων μήτε τῶν θείων αἰδώς τις εἰσέρχεται, πάντα φύρων καὶ συγχέων διά τε τὰς ἀμετρίας τῶν παθῶν καὶ τὰς τῶν κακιῶν ὑπερβολάς, ὥστε ὧν ἂν ἐφάψηται πραγμάτων πάντ’ ἐστὶν ἐπίληπτα τῇ τοῦ δρῶντος συμμεταβάλλοντα μοχθηρίᾳ· καὶ γὰρ κατὰ τοὐναντίον αἱ πράξεις τῶν ἀγαθῶν ἐπαινεταί, βελτιούμεναι ταῖς τῶν ἐνεργούντων ἀρεταῖς, ἐπειδὴ πέφυκέ πως τὰ γινόμενα τοῖς δρῶσιν ἐξομοιοῦσθαι.", "st": "209"}], []);})();
